-- 35 minimal demo_cached_responses (general_smb × 7 demos × 5 interactions)
INSERT INTO demo_cached_responses (demo_type, vertical, trigger_key, sequence_order, prompt_text, response_text, active) VALUES
  ('chatbot', 'general_smb', 'welcome', 1, 'Start conversation', 'Welcome! I''m your AI business assistant. I can help with customer inquiries, scheduling, and general business questions. What would you like to explore?', true),
  ('chatbot', 'general_smb', 'capabilities', 2, 'What can you do?', 'I can handle customer FAQs, appointment scheduling, order status inquiries, product recommendations, and after-hours support. I learn from your business data to give accurate, contextual responses.', true),
  ('chatbot', 'general_smb', 'pricing_inquiry', 3, 'How does pricing work?', 'Our chatbot solutions start with understanding your business needs. We analyze your most common customer interactions, build a custom knowledge base, and deploy an AI assistant that handles 70-80% of routine inquiries automatically.', true),
  ('chatbot', 'general_smb', 'integration', 4, 'How does it integrate?', 'The AI chatbot integrates with your existing website, CRM, and communication tools. Setup typically takes 2-3 weeks including training on your business data and testing.', true),
  ('chatbot', 'general_smb', 'get_started', 5, 'How do I get started?', 'Book a discovery call and we''ll analyze your current customer interaction patterns. We''ll identify the highest-impact automation opportunities and build a custom implementation plan.', true),
  ('analytics', 'general_smb', 'welcome', 1, 'Start analytics demo', 'Welcome to the Predictive Analytics demo. I''ll show you how AI can transform your business data into actionable forecasts. What aspect interests you most?', true),
  ('analytics', 'general_smb', 'revenue_forecast', 2, 'Show revenue forecast', 'Based on historical patterns, AI can predict revenue trends 3-6 months ahead with 85%+ accuracy. It identifies seasonal patterns, growth trajectories, and early warning signs of downturns.', true),
  ('analytics', 'general_smb', 'customer_insights', 3, 'Customer behavior analysis', 'AI analyzes purchase history, engagement patterns, and demographic data to identify your most valuable customer segments and predict churn risk before it happens.', true),
  ('analytics', 'general_smb', 'inventory', 4, 'Inventory optimization', 'Predictive models optimize stock levels by forecasting demand, reducing carrying costs by 15-25% while preventing stockouts. It factors in seasonality, promotions, and market trends.', true),
  ('analytics', 'general_smb', 'get_started', 5, 'How to implement?', 'We start with a data audit to assess your current data quality and sources. Then we build custom models tailored to your KPIs. Most SMBs see ROI within the first quarter.', true),
  ('email_sms', 'general_smb', 'welcome', 1, 'Start email workflow demo', 'Welcome to the Email & SMS Workflow demo. I''ll show you how AI creates personalized communication sequences that feel human-written. What would you like to see?', true),
  ('email_sms', 'general_smb', 'welcome_series', 2, 'Show welcome series', 'Here''s an AI-generated welcome series: personalized onboarding emails that adapt based on how each customer interacts. Open rates typically improve 40-60% vs generic templates.', true),
  ('email_sms', 'general_smb', 're_engagement', 3, 'Re-engagement campaign', 'AI identifies at-risk customers and generates personalized win-back messages. It picks the right channel (email vs SMS), timing, and offer based on individual behavior patterns.', true),
  ('email_sms', 'general_smb', 'ab_testing', 4, 'AI A/B testing', 'Instead of manual A/B tests, AI continuously optimizes subject lines, send times, and content variations. It learns from every interaction to improve future campaigns automatically.', true),
  ('email_sms', 'general_smb', 'get_started', 5, 'Implementation process', 'We integrate with your existing email platform (Mailchimp, SendGrid, etc.) and CRM. AI analyzes your past campaigns to establish baselines, then starts generating optimized content.', true),
  ('doc_processing', 'general_smb', 'welcome', 1, 'Start document processing demo', 'Welcome to Document Processing. I''ll demonstrate how AI extracts, classifies, and processes business documents automatically. What type of documents do you work with?', true),
  ('doc_processing', 'general_smb', 'invoice_processing', 2, 'Invoice processing', 'AI reads invoices from any format (PDF, scan, email), extracts key fields (vendor, amount, line items, dates), validates against PO numbers, and routes for approval. Accuracy: 95%+.', true),
  ('doc_processing', 'general_smb', 'contract_review', 3, 'Contract analysis', 'AI scans contracts for key terms, obligations, deadlines, and risk clauses. It flags non-standard language and generates summary reports highlighting action items.', true),
  ('doc_processing', 'general_smb', 'data_extraction', 4, 'Data extraction', 'From forms, receipts, reports — AI extracts structured data and feeds it directly into your systems. No manual data entry. Handles handwriting, tables, and multi-page documents.', true),
  ('doc_processing', 'general_smb', 'get_started', 5, 'Getting started', 'Send us sample documents and we''ll run a proof-of-concept extraction. We''ll measure accuracy against your current process and project time/cost savings.', true),
  ('competitive_analysis', 'general_smb', 'welcome', 1, 'Start competitive analysis', 'Welcome to Competitive Analysis. Enter your business name and I''ll generate an AI-powered competitive landscape report. What''s your business?', true),
  ('competitive_analysis', 'general_smb', 'market_position', 2, 'Analyze market position', 'AI maps your competitive landscape by analyzing online presence, pricing signals, customer reviews, and market positioning. It identifies gaps and opportunities in real-time.', true),
  ('competitive_analysis', 'general_smb', 'competitor_strengths', 3, 'Competitor strengths', 'For each competitor, AI evaluates their digital presence, customer sentiment, product/service offerings, and marketing strategies. You get actionable intelligence, not just data.', true),
  ('competitive_analysis', 'general_smb', 'opportunities', 4, 'Find opportunities', 'AI identifies underserved market segments, pricing opportunities, and areas where competitors are weak. These become your strategic advantages.', true),
  ('competitive_analysis', 'general_smb', 'get_started', 5, 'Full analysis', 'Book a discovery call and we''ll run a comprehensive competitive analysis for your business. You''ll receive a detailed PDF report with actionable recommendations.', true),
  ('doc_drafting', 'general_smb', 'welcome', 1, 'Start document drafting', 'Welcome to Document Drafting. I''ll show how AI generates professional business documents tailored to your needs. What type of document interests you?', true),
  ('doc_drafting', 'general_smb', 'proposal', 2, 'Generate a proposal', 'AI drafts professional proposals incorporating your services, pricing, timelines, and terms. It adapts tone and structure based on the prospect''s industry and size.', true),
  ('doc_drafting', 'general_smb', 'agreement', 3, 'Service agreement', 'Generate service agreements with standard clauses customized to your business. AI ensures consistency across documents while allowing per-client customization.', true),
  ('doc_drafting', 'general_smb', 'report', 4, 'Business report', 'AI compiles data from multiple sources into formatted reports with executive summaries, charts, and actionable recommendations. Saves hours of manual report writing.', true),
  ('doc_drafting', 'general_smb', 'get_started', 5, 'Implementation', 'We start by templating your most common documents, then train AI on your style and requirements. Most businesses automate 60-70% of routine document creation.', true),
  ('marketing_engine', 'general_smb', 'welcome', 1, 'Start marketing engine demo', 'Welcome to the Marketing Engine. I''ll demonstrate AI-powered content creation and campaign optimization. What marketing challenge are you facing?', true),
  ('marketing_engine', 'general_smb', 'content_creation', 2, 'AI content creation', 'AI generates blog posts, social media content, ad copy, and email campaigns aligned with your brand voice. It maintains consistency while scaling content production 10x.', true),
  ('marketing_engine', 'general_smb', 'seo_optimization', 3, 'SEO optimization', 'AI analyzes search trends, competitor rankings, and your existing content to generate SEO-optimized articles. It identifies keyword opportunities and content gaps automatically.', true),
  ('marketing_engine', 'general_smb', 'campaign_optimization', 4, 'Campaign optimization', 'AI monitors campaign performance across channels and automatically adjusts targeting, creative, and budget allocation to maximize ROI.', true),
  ('marketing_engine', 'general_smb', 'get_started', 5, 'Get started', 'We analyze your current marketing stack, brand guidelines, and performance data. Then we deploy AI tools that amplify your existing efforts — not replace your strategy.', true)
ON CONFLICT (demo_type, vertical, trigger_key) DO UPDATE SET
  sequence_order = EXCLUDED.sequence_order,
  prompt_text = EXCLUDED.prompt_text,
  response_text = EXCLUDED.response_text,
  active = EXCLUDED.active;

-- Additional 35 demo_cached_responses (general_smb × 7 demos × entries 6-10)
INSERT INTO demo_cached_responses (demo_type, vertical, trigger_key, sequence_order, prompt_text, response_text, active) VALUES
  -- chatbot 6-10
  ('chatbot', 'general_smb', 'response_time', 6, 'How fast are responses?', 'Average response time is under 2 seconds. The AI handles multiple conversations simultaneously with no wait times, even during peak hours. Customers get instant, accurate answers 24/7.', true),
  ('chatbot', 'general_smb', 'languages', 7, 'Multi-language support?', 'The chatbot supports 30+ languages with automatic detection. It seamlessly switches languages mid-conversation and maintains context. Great for businesses serving diverse communities.', true),
  ('chatbot', 'general_smb', 'handoff', 8, 'Human handoff process', 'When the AI detects complex issues or frustrated sentiment, it smoothly transfers to a human agent with full conversation context. Your team picks up exactly where the AI left off — no repeat explanations.', true),
  ('chatbot', 'general_smb', 'training', 9, 'How is it trained?', 'We train on your FAQ database, product catalog, past support tickets, and company policies. The AI continuously learns from new interactions and flagged corrections. Monthly accuracy reports keep you informed.', true),
  ('chatbot', 'general_smb', 'roi', 10, 'What ROI can I expect?', 'Most SMBs see 40-60% reduction in support ticket volume within 90 days. That translates to significant cost savings while improving customer satisfaction scores. We measure and report ROI monthly.', true),

  -- analytics 6-10
  ('analytics', 'general_smb', 'churn_prediction', 6, 'Predict customer churn', 'AI identifies customers likely to churn 30-60 days before they leave. It scores each customer on risk factors — declining engagement, support issues, competitive browsing — so you can intervene early.', true),
  ('analytics', 'general_smb', 'pricing', 7, 'Dynamic pricing insights', 'AI analyzes competitor pricing, demand elasticity, and customer willingness-to-pay to recommend optimal price points. Real-time adjustments can increase margin by 5-15%.', true),
  ('analytics', 'general_smb', 'marketing_roi', 8, 'Marketing spend analysis', 'AI attributes revenue to specific marketing channels and campaigns with multi-touch modeling. It identifies your most efficient spend and recommends budget reallocation for maximum ROI.', true),
  ('analytics', 'general_smb', 'anomaly_detection', 9, 'Anomaly detection', 'AI monitors your key metrics 24/7 and alerts you to unusual patterns — sudden drops in sales, spikes in returns, or unexpected cost increases. Early detection prevents small issues from becoming crises.', true),
  ('analytics', 'general_smb', 'dashboard', 10, 'Custom dashboards', 'AI generates natural-language summaries of your dashboards. Ask questions like "Why did revenue drop last week?" and get specific, data-backed explanations instead of just charts.', true),

  -- email_sms 6-10
  ('email_sms', 'general_smb', 'segmentation', 6, 'Smart segmentation', 'AI automatically segments your audience based on behavior, purchase history, and engagement patterns. Each segment gets tailored messaging that resonates with their specific needs and buying stage.', true),
  ('email_sms', 'general_smb', 'drip_campaigns', 7, 'Automated drip campaigns', 'AI designs multi-step drip campaigns that adapt in real-time. If a customer opens but doesn''t click, the next message adjusts. If they purchase, they move to a post-sale nurture track automatically.', true),
  ('email_sms', 'general_smb', 'personalization', 8, 'Hyper-personalization', 'Beyond "Hi {name}" — AI personalizes content, offers, and timing for each recipient. Product recommendations, dynamic content blocks, and send-time optimization based on individual behavior.', true),
  ('email_sms', 'general_smb', 'sms_automation', 9, 'SMS automation', 'AI determines when SMS vs email is more effective for each customer. Appointment reminders, shipping updates, flash sales — all timed for maximum engagement with smart frequency capping.', true),
  ('email_sms', 'general_smb', 'compliance', 10, 'Compliance & deliverability', 'Built-in CAN-SPAM and TCPA compliance. AI monitors deliverability metrics, manages unsubscribes, and automatically adjusts sending patterns to maintain high inbox placement rates.', true),

  -- doc_processing 6-10
  ('doc_processing', 'general_smb', 'receipt_scanning', 6, 'Receipt & expense processing', 'Photograph receipts and AI extracts vendor, amount, category, and tax info. Integrates with accounting software for automatic expense categorization and report generation. No more manual data entry.', true),
  ('doc_processing', 'general_smb', 'form_processing', 7, 'Form processing', 'AI processes applications, surveys, and registration forms from any format. It handles checkboxes, signatures, handwriting, and multi-page forms with field validation built in.', true),
  ('doc_processing', 'general_smb', 'classification', 8, 'Document classification', 'AI automatically sorts incoming documents by type — invoices, contracts, correspondence, tax forms — and routes them to the right department or workflow. 98% classification accuracy.', true),
  ('doc_processing', 'general_smb', 'compliance_check', 9, 'Compliance checking', 'AI reviews documents against your compliance requirements and flags missing fields, expired certifications, or non-compliant language. Reduces audit preparation time by 70%.', true),
  ('doc_processing', 'general_smb', 'batch_processing', 10, 'Batch processing', 'Process hundreds of documents simultaneously. AI maintains accuracy at scale — whether it''s year-end tax documents, quarterly reports, or a backlog of unprocessed invoices.', true),

  -- competitive_analysis 6-10
  ('competitive_analysis', 'general_smb', 'pricing_analysis', 6, 'Pricing comparison', 'AI monitors competitor pricing across products and services, tracks changes over time, and identifies pricing tiers and strategies. You see exactly where you''re positioned in the market.', true),
  ('competitive_analysis', 'general_smb', 'review_sentiment', 7, 'Review sentiment analysis', 'AI analyzes thousands of competitor reviews to identify recurring complaints and praised features. These insights reveal exactly what customers wish competitors did better — your opportunity.', true),
  ('competitive_analysis', 'general_smb', 'digital_presence', 8, 'Digital presence audit', 'AI evaluates competitors'' websites, SEO rankings, social media activity, and online advertising. You get a clear picture of their digital strategy and where you can outperform them.', true),
  ('competitive_analysis', 'general_smb', 'trend_monitoring', 9, 'Market trend monitoring', 'AI tracks industry trends, emerging competitors, and market shifts relevant to your business. Monthly intelligence briefings keep you ahead of changes before they impact your revenue.', true),
  ('competitive_analysis', 'general_smb', 'swot', 10, 'SWOT analysis', 'AI generates detailed SWOT analyses for your business and each competitor. Strengths, weaknesses, opportunities, and threats are backed by data — not guesswork — making strategy planning concrete.', true),

  -- doc_drafting 6-10
  ('doc_drafting', 'general_smb', 'email_templates', 6, 'Email templates', 'AI creates professional email templates for common scenarios — follow-ups, introductions, proposals, thank-yous. Each template adapts to the recipient''s context and your brand voice.', true),
  ('doc_drafting', 'general_smb', 'sop', 7, 'Standard operating procedures', 'AI helps draft SOPs by structuring your process knowledge into clear, step-by-step documents. It ensures consistency, includes safety notes, and formats for easy team reference.', true),
  ('doc_drafting', 'general_smb', 'marketing_copy', 8, 'Marketing copy', 'Generate ad copy, landing page text, brochure content, and social media posts. AI maintains your brand voice while optimizing for engagement and conversion across all formats.', true),
  ('doc_drafting', 'general_smb', 'legal_basics', 9, 'Basic legal documents', 'AI drafts NDAs, terms of service, privacy policies, and basic agreements using industry-standard templates. Always have these reviewed by legal counsel before use.', true),
  ('doc_drafting', 'general_smb', 'formatting', 10, 'Smart formatting', 'AI applies professional formatting — headers, tables, bullet points, page breaks — automatically. Documents look polished and consistent whether it''s a one-page letter or a 20-page report.', true),

  -- marketing_engine 6-10
  ('marketing_engine', 'general_smb', 'social_media', 6, 'Social media content', 'AI generates platform-specific content — LinkedIn thought leadership, Instagram captions, Twitter threads, Facebook posts. Each piece is optimized for the platform''s algorithm and audience expectations.', true),
  ('marketing_engine', 'general_smb', 'ad_copy', 7, 'Ad copy generation', 'Generate Google Ads, Facebook Ads, and display ad copy with AI. It creates multiple variations, suggests targeting criteria, and optimizes headlines for click-through rates.', true),
  ('marketing_engine', 'general_smb', 'brand_voice', 8, 'Brand voice consistency', 'AI learns your brand voice, tone guidelines, and messaging framework. Every piece of content — from tweets to whitepapers — sounds authentically you, just produced 10x faster.', true),
  ('marketing_engine', 'general_smb', 'competitor_content', 9, 'Competitor content analysis', 'AI monitors competitor content strategies — what topics they cover, how often they publish, what resonates with their audience. Use these insights to differentiate your content.', true),
  ('marketing_engine', 'general_smb', 'performance_reports', 10, 'Performance reporting', 'AI compiles content performance data across all channels into actionable reports. It identifies what''s working, what''s not, and recommends specific content strategy adjustments.', true)
ON CONFLICT (demo_type, vertical, trigger_key) DO UPDATE SET
  sequence_order = EXCLUDED.sequence_order,
  prompt_text = EXCLUDED.prompt_text,
  response_text = EXCLUDED.response_text,
  active = EXCLUDED.active;

-- =============================================================================
-- Construction vertical — 70 demo_cached_responses (7 demos × 10 each)
-- =============================================================================
INSERT INTO demo_cached_responses (demo_type, vertical, trigger_key, sequence_order, prompt_text, response_text, active) VALUES
  ('chatbot', 'construction', 'welcome', 1, 'Start conversation', 'Welcome to your AI-powered construction operations assistant. I can help you manage RFIs, track submittals, handle change orders, and streamline communication between your GC and subcontractors. What project challenge can I help you tackle today?', true),
  ('chatbot', 'construction', 'rfi_inquiry', 2, 'How do I track open RFIs?', 'I can pull up all open RFIs across your active projects, sorted by due date and responsible party. Currently you have 14 open RFIs — 6 are overdue, with the oldest from your masonry sub on the CMU wall layout. Want me to draft a follow-up notice to the architect?', true),
  ('chatbot', 'construction', 'submittal_log', 3, 'What submittals are pending approval?', 'Your submittal log shows 23 items awaiting action: 11 pending architect review, 8 returned with comments, and 4 approved but not yet distributed to subs. The structural steel shop drawings have been sitting with the engineer for 19 days — that''s past the 14-day review window in your contract.', true),
  ('chatbot', 'construction', 'change_order_status', 4, 'Give me a change order summary', 'You have 9 open change order requests totaling $287,450 in potential additions to the contract. Three PCOs from your electrical sub have been pending GC approval for over 30 days, which may affect their next AIA pay application. I can generate a change order aging report right now.', true),
  ('chatbot', 'construction', 'lien_waiver_tracking', 5, 'Are all lien waivers collected?', 'For the most recent pay period, you''re missing conditional lien waivers from 3 subcontractors: the plumbing sub, the drywall crew, and your rebar supplier. Releasing payment without these creates lien exposure on the project. Want me to send automated collection reminders?', true),
  ('chatbot', 'construction', 'safety_incident', 6, 'Log a safety incident', 'I''ll help you document this incident for OSHA compliance. I need the date, time, location on site, workers involved, and a description of what occurred. If this is a recordable incident under OSHA 300 log criteria, I''ll flag it for your safety officer and generate the required documentation automatically.', true),
  ('chatbot', 'construction', 'schedule_update', 7, 'What''s the current project schedule status?', 'Your 4-week lookahead shows the framing crew is 6 days behind on Level 3, which will push MEP rough-in and delay the drywall sub''s start. The critical path runs through the elevator shaft concrete pour scheduled for next Thursday — any further delay there impacts your substantial completion date.', true),
  ('chatbot', 'construction', 'bid_inquiry', 8, 'Help me review a subcontractor bid', 'I can analyze bid leveling across your received proposals. Paste the bid values or upload the spreadsheet and I''ll flag scope gaps, unit price outliers, and missing line items like bonding, prevailing wage compliance, or cleanup. I''ll also check if each bidder has the required insurance certificates on file.', true),
  ('chatbot', 'construction', 'aia_billing', 9, 'When is the next AIA pay app due?', 'Your AIA G702/G703 applications are due to the owner by the 25th of each month. Based on your current schedule of values, I estimate this month''s draw at approximately $1.2M — 73% complete on structural, 45% on MEP rough-in. I can pre-fill the continuation sheets from your cost tracking data.', true),
  ('chatbot', 'construction', 'get_started', 10, 'Ready to streamline your operations?', 'You''ve seen how AI can cut hours off RFI management, submittal tracking, and payment administration. Let''s connect your project management platform — whether it''s Procore, Autodesk, or a custom setup — and get you live within 48 hours. Schedule your onboarding call with our construction team today.', true),

  ('analytics', 'construction', 'welcome', 1, 'Start conversation', 'Welcome to your construction analytics dashboard. I provide real-time insights across project financials, schedule performance, subcontractor productivity, and risk exposure. Your portfolio currently spans 7 active projects with $43M in contract value under management.', true),
  ('analytics', 'construction', 'cost_variance', 2, 'Show cost variance by trade', 'Concrete and masonry are running 12% over budget driven by rebar material escalation and CMU delivery delays. MEP trades are tracking 4% favorable due to efficient prefab coordination. Your overall project cost performance index (CPI) is 0.94 — flag this for your next owner''s meeting.', true),
  ('analytics', 'construction', 'change_order_analytics', 3, 'Analyze change order trends', 'Over the last 6 months, 61% of your change orders originated from RFI responses and design clarifications — a sign of incomplete drawings at bid. Electrical accounts for 34% of CO value, primarily conduit rerouting around undisclosed structural conflicts. Upstream design coordination could save an estimated $180K per project.', true),
  ('analytics', 'construction', 'schedule_performance', 4, 'What is our schedule performance index?', 'Your portfolio-wide SPI is 0.91, indicating you''re completing about 91 cents of scheduled work for every dollar of planned work. The highway bridge project is your worst performer at SPI 0.78, driven by weather delays and a concrete cure hold. Two projects are ahead of schedule — both have strong superintendent to foreman ratios.', true),
  ('analytics', 'construction', 'subcontractor_performance', 5, 'Score my subcontractor performance', 'Your top-performing subs by composite score (schedule, quality, safety, RFI response time) are your structural steel and elevator contractors. Your roofing sub ranks lowest — they''ve had 2 safety write-ups, 4 punchlist comebacks, and average 11 days to respond to submittals. Consider rebidding that scope for your next project.', true),
  ('analytics', 'construction', 'safety_metrics', 6, 'Review safety KPIs across projects', 'Portfolio total recordable incident rate (TRIR) is 1.8, below the industry average of 2.9 for commercial construction. However, near-miss reporting is down 40% this quarter — often a leading indicator of unreported incidents. Your highway project has had zero OSHA recordables in 210 days; recognize that superintendent''s performance.', true),
  ('analytics', 'construction', 'bid_win_rate', 7, 'Analyze our bid win rate', 'Your overall bid hit rate is 24% over the trailing 12 months, with a sweet spot on projects between $5M–$15M where you win 38% of bids. Hard bid public work remains competitive at 11% win rate. Negotiated GMP contracts with repeat clients are your most profitable work — 6.2% average net margin versus 2.1% on hard bid.', true),
  ('analytics', 'construction', 'cash_flow_forecast', 8, 'Project our cash flow for next quarter', 'Based on your current draw schedules and approved AIA applications, projected cash inflow for Q2 is $8.7M. Outstanding retainage across all projects is $2.1M — $640K of that is eligible for release upon substantial completion milestones next month. Two subcontractors are showing signs of financial stress based on delayed pay app submissions.', true),
  ('analytics', 'construction', 'prevailing_wage_compliance', 9, 'Are we prevailing wage compliant?', 'Your certified payroll submissions for the municipal library project are current through last week. However, your masonry sub''s fringe benefit calculations appear 8% below the Davis-Bacon wage determination for your county — this creates liability for the GC as the prime contractor. I''ve flagged it for your compliance officer.', true),
  ('analytics', 'construction', 'get_started', 10, 'Ready to make data-driven decisions?', 'These analytics can be live across your entire portfolio within one week of integration. We connect directly to Procore, Sage, Viewpoint, and most project management platforms — no manual data entry required. Book a 30-minute demo with our construction analytics team to see your own project data in the dashboard.', true),

  ('email_sms', 'construction', 'welcome', 1, 'Start conversation', 'Welcome to your construction communications hub. This platform automates RFI notifications, submittal status alerts, lien waiver collection reminders, and safety bulletins across your GC team, subcontractors, and owner. Reach the right people at the right time — no more chasing paper trails.', true),
  ('email_sms', 'construction', 'rfi_notification', 2, 'Send RFI status update', 'RFI #087 — Roof Drain Sizing at Grid C4 — has been sent to the architect of record with a 7-day response requested per contract Section 4.2. Your structural sub and MEP coordinator have been copied automatically. If no response is received by Friday, an escalation notice will go to the owner''s rep.', true),
  ('email_sms', 'construction', 'lien_waiver_reminder', 3, 'Send lien waiver collection reminder', 'Automated text and email reminders have been dispatched to your 3 outstanding subcontractors: "Payment for Application #8 is on hold pending your conditional lien waiver. Please submit via the portal link below by 5PM Friday to avoid payment delay." Response rate for automated reminders averages 87% within 24 hours.', true),
  ('email_sms', 'construction', 'safety_alert', 4, 'Blast a safety alert to site crew', 'Safety bulletin sent via SMS to all 47 credentialed workers on the downtown hotel project: "TOOLBOX TALK MANDATORY — Friday 7AM pre-shift. Topic: Elevated work and fall protection over the Level 4 deck pour. Hard hat, harness, and tool tether required in all swing stage areas. No exceptions — OSHA 1926.502 enforcement in effect."', true),
  ('email_sms', 'construction', 'submittal_followup', 5, 'Follow up on overdue submittals', 'Automated follow-up emails have been sent to 4 subs with submittals more than 5 days overdue per your project schedule. Your electrical sub received a second notice for the panel schedule submittal — it''s on the critical path for rough-in inspections. A third notice automatically escalates to your project executive.', true),
  ('email_sms', 'construction', 'weather_delay_notice', 6, 'Notify team of weather delay', 'Weather delay notice sent to owner, architect, all subcontractor foremen, and your bonding company: "Operations suspended today due to high wind advisory — crane operations per OSHA 1926.1416 suspended above 30 mph. Time impact to be documented and submitted as a Force Majeure notice per contract Section 8.3.2."', true),
  ('email_sms', 'construction', 'pay_app_reminder', 7, 'Remind subs to submit pay applications', 'SMS reminders sent to all 12 active subcontractors: "AIA G702 pay applications due by the 20th — submit via the portal with updated schedule of values, certified payroll (if prevailing wage), and conditional lien waiver. Late submissions will be processed on the following month''s draw cycle."', true),
  ('email_sms', 'construction', 'inspection_notice', 8, 'Schedule and notify inspection', 'Framing inspection confirmation sent to the building department, your superintendent, and the owner''s project manager for Tuesday at 9AM. Automated checklist distributed to site team covering blocking, bracing, fire blocking, and nailing pattern documentation. Inspector contact info and permit number included in the notification.', true),
  ('email_sms', 'construction', 'change_order_approval', 9, 'Notify team of approved change order', 'Change Order #14 — Additional Waterproofing at Foundation Wall — for $18,750 has been fully executed. Notification sent to your project manager, superintendent, accounting team, and the concrete sub. Updated contract value of $4,312,000 reflected in your AIA billing system. Retainage adjusted accordingly.', true),
  ('email_sms', 'construction', 'get_started', 10, 'Automate your field communications', 'Stop playing phone tag and chasing paper. Our communications platform keeps your GC team, subs, inspectors, and owners in sync automatically — from first RFI to final lien waiver. Setup takes less than a day and integrates with your existing project management tools. Get started with a free 30-day pilot on your next project.', true),

  ('doc_processing', 'construction', 'welcome', 1, 'Start conversation', 'Welcome to AI-powered document processing for construction. I extract, classify, and route critical data from contracts, AIA pay applications, submittals, lien waivers, certified payroll, insurance certificates, and RFIs — eliminating manual data entry and reducing processing errors across your project lifecycle.', true),
  ('doc_processing', 'construction', 'aia_extraction', 2, 'Process an AIA pay application', 'I''ve processed the G702/G703 from your framing subcontractor. Extracted values: scheduled value $892,000, work completed to date $714,000 (80%), materials stored $22,000, retainage held $73,600, net due this period $89,400. One line item — labor burden on overtime — exceeds your approved unit cost by 14%. Flagged for PM review before approval.', true),
  ('doc_processing', 'construction', 'lien_waiver_processing', 3, 'Process received lien waivers', 'Batch processed 11 lien waivers received this week. 9 conditional waivers match payment amounts in your system exactly. 1 waiver from the electrical sub shows a discrepancy — the amount listed ($47,200) differs from your approved pay app ($44,800). 1 waiver is missing a notarization required by your state''s mechanics lien statute.', true),
  ('doc_processing', 'construction', 'insurance_cert_review', 4, 'Review subcontractor insurance certificates', 'Processed ACORD 25 certificates for 8 subcontractors. 6 are compliant with your contract requirements. Your HVAC sub''s general liability coverage expired 11 days ago — work should be suspended until renewed. Your concrete sub''s additional insured endorsement names the wrong entity; the owner''s correct legal name must appear on the certificate.', true),
  ('doc_processing', 'construction', 'rfi_log_extraction', 5, 'Extract and log RFI data', 'Processed 34 RFI documents from your project email archive. Extracted RFI numbers, originating parties, question summaries, response dates, and cost/schedule impact flags. 6 RFIs have responses that indicate potential change order scope — these have been tagged and routed to your project manager for PCO evaluation. Log exported to your Procore template.', true),
  ('doc_processing', 'construction', 'certified_payroll', 6, 'Validate certified payroll submissions', 'Reviewed 6 certified payroll reports for prevailing wage compliance on the municipal recreation center project. All straight-time rates meet or exceed the applicable Davis-Bacon wage determination. However, your concrete sub is classifying form setters as Laborer instead of Carpenter — a misclassification that could trigger a DOL audit and back-wage liability.', true),
  ('doc_processing', 'construction', 'contract_extraction', 7, 'Extract key contract terms', 'Extracted critical dates and obligations from your prime contract: liquidated damages $2,500/day after substantial completion, retainage releases to 5% at 50% completion, 21-day notice required for all change order claims, and 72-hour written notice required before concealing work. I''ve added all milestone dates to your project calendar with automated reminders.', true),
  ('doc_processing', 'construction', 'submittal_register', 8, 'Build submittal register from specs', 'Analyzed Division 03 through Division 16 specifications and auto-populated your submittal register with 187 required items, lead times, responsible parties, and spec section references. 23 submittals are on the critical path based on your current schedule — I''ve flagged required submission dates working backward from your procurement milestones.', true),
  ('doc_processing', 'construction', 'close_out_docs', 9, 'Process project closeout documents', 'Compiling closeout package for Riverside Office Complex: collected O&M manuals for 14 systems, 6 of 8 warranty documents received (HVAC and roofing still outstanding), as-built drawings reconciled against final RFI responses, and certificate of occupancy uploaded. Punchlist completion is at 94% — 7 open items remain before final retainage release.', true),
  ('doc_processing', 'construction', 'get_started', 10, 'Eliminate manual document processing', 'Your team processes hundreds of pages of contracts, pay apps, and compliance documents every month. Our AI cuts that time by 80% while catching errors that create legal and financial exposure. We handle AIA billing, lien waivers, certified payroll, insurance certs, and more. Schedule a document processing audit and see the ROI in your first 30 days.', true),

  ('competitive_analysis', 'construction', 'welcome', 1, 'Start conversation', 'Welcome to your construction competitive intelligence platform. I track competitor bid activity, market pricing trends, subcontractor relationships, bonding capacity signals, and project award data — giving your estimating and business development teams the edge on every pursuit. What market or competitor would you like to analyze?', true),
  ('competitive_analysis', 'construction', 'competitor_bid_activity', 2, 'Who are we losing bids to?', 'Over the last 12 months, you''ve lost 14 hard bids to three primary competitors. Johnson & Sons Construction has beaten you 6 times — consistently coming in 4–7% below your number on tilt-up and precast work. Market data suggests they have a preferred relationship with the regional precast supplier that gives them a material cost advantage.', true),
  ('competitive_analysis', 'construction', 'market_pricing', 3, 'What are current market labor rates?', 'Prevailing wage and open shop labor rates have increased 6.8% year-over-year in your metro area. Carpenter and ironworker trades are tightest — foreman-level skilled labor is commanding $8–$12/hour over scale due to workforce shortages. Concrete formwork labor is your highest risk line item for bid escalation over the next 18 months.', true),
  ('competitive_analysis', 'construction', 'subcontractor_market', 4, 'Analyze the local subcontractor market', 'Your local MEP subcontractor pool has consolidated — two mechanical subs merged last quarter, reducing competitive tension on HVAC bids. Electrical capacity is constrained; only 3 subs can bond projects over $8M in your market. For your upcoming $22M mixed-use pursuit, you should begin sub outreach 90 days earlier than your standard process.', true),
  ('competitive_analysis', 'construction', 'bonding_intelligence', 5, 'What is our bonding capacity versus competitors?', 'Your current single/aggregate bonding capacity positions you competitively for projects up to $30M. Two of your top competitors recently expanded their bonding lines, enabling them to pursue the $65M county courthouse GMP — a project you''re currently not positioned to bond. Growing your net worth by $2M would unlock the next bonding tier.', true),
  ('competitive_analysis', 'construction', 'material_cost_trends', 6, 'Track construction material cost trends', 'Rebar (Grade 60) is up 18% from Q1 of last year driven by tariff impacts on imported steel. Ready-mix concrete has increased 9% driven by aggregate and fuel costs. Structural lumber is down 12% from peak but volatile. Your estimating database should be refreshed monthly — using stale unit costs on a 12-month bid is your biggest margin risk right now.', true),
  ('competitive_analysis', 'construction', 'owner_relationship_map', 7, 'Map owner relationships in our target market', 'In your target healthcare and education verticals, Meridian Construction holds preferred contractor status with 3 of the 5 largest hospital systems in the region. Your firm has completed work for 2 of those owners but lacks a GMP track record with them. Pursuing a smaller renovation project as a teaming partner could position you for upcoming major capital programs.', true),
  ('competitive_analysis', 'construction', 'win_rate_by_delivery', 8, 'Compare win rates by project delivery method', 'Design-build pursuits are your strongest delivery method at a 41% win rate — your integrated team and past performance score favorably with public owners. Design-bid-build hard bids remain competitive at 22%. Construction management at-risk (CMAR) is an underexplored opportunity; you''ve only pursued 3 in 2 years and won 2, suggesting strong capability that is undermarketed.', true),
  ('competitive_analysis', 'construction', 'workforce_benchmarking', 9, 'How does our workforce compare to competitors?', 'Your craft workforce retention rate of 78% outperforms the regional average of 63% — a significant competitive advantage on multi-year projects. However, your superintendent-to-project ratio is 1:1.8 versus the industry best practice of 1:1 on complex projects. Competitors with stronger field supervision are outperforming on quality scores and schedule adherence for negotiated clients.', true),
  ('competitive_analysis', 'construction', 'get_started', 10, 'Gain the competitive edge', 'In construction, winning the right work at the right margin is everything. Our competitive intelligence platform gives your estimators and BD team the data to bid smarter, pursue better, and grow profitably. Let''s run a full competitive analysis on your top 3 target project types — book a strategy session with our construction market team today.', true),

  ('doc_drafting', 'construction', 'welcome', 1, 'Start conversation', 'Welcome to AI-powered document drafting for construction. I generate professional RFI responses, change order proposals, subcontract scopes of work, OSHA safety plans, AIA supplemental conditions, notice letters, and more — using your project data and construction industry standards. What document can I draft for you today?', true),
  ('doc_drafting', 'construction', 'change_order_draft', 2, 'Draft a change order proposal', 'I''ve drafted PCO #19 — Undisclosed Subsurface Obstructions at Grid Lines D through F. The proposal includes direct labor (12 hours ironworker, 8 hours operating engineer), equipment (excavator standby 6 hours at $185/hr), material disposal, and 15% overhead and profit per your contract terms. Total proposed amount: $9,840. Includes a 3-day time impact notice per contract Section 7.4.', true),
  ('doc_drafting', 'construction', 'rfi_response_draft', 3, 'Draft an RFI response', 'RFI #042 Response drafted: "The CMU wall at Grid B3 shall be constructed per revised Detail 5/S-204 issued via this RFI response. Reinforcing shall be #5 at 24" o.c. each way, grouted solid. Contractor shall verify coordination with electrical conduit shown on E-301 prior to placing grout. No cost or schedule impact is anticipated from this clarification."', true),
  ('doc_drafting', 'construction', 'subcontract_scope', 4, 'Draft a subcontract scope of work', 'Concrete subcontract scope drafted for Parkview Medical Office Building. Scope includes: all formwork, rebar placement per structural drawings, ready-mix supply and placement, flatwork finishing, curing, and form removal. Exclusions clearly listed: site utilities, underslab MEP sleeves, and elevator pit waterproofing. Prevailing wage, certified payroll, and OSHA 10 requirements called out per Division 01 General Requirements.', true),
  ('doc_drafting', 'construction', 'notice_letter', 5, 'Draft a contract notice letter', 'Notice of Potential Delay drafted per contract Section 8.3: "Please be advised that the Owner-directed design change to the curtainwall system, communicated via ASI #7 dated March 15, constitutes a potential impact to the contract schedule. Contractor hereby provides timely notice of this potential delay impact. Detailed time and cost analysis will follow within 21 days per contract requirements."', true),
  ('doc_drafting', 'construction', 'safety_plan', 6, 'Draft a site safety plan section', 'Fall Protection Plan drafted per OSHA 29 CFR 1926.502: scope covers all work at elevations above 6 feet on the Westfield Tower project. Plan includes leading edge protection requirements, personal fall arrest system specifications (Class II harness, 6-ft shock-absorbing lanyard, anchors rated 5,000 lbs), and hole cover standards. Competent person designations and daily inspection log included.', true),
  ('doc_drafting', 'construction', 'punch_list_letter', 7, 'Draft a punchlist completion letter', 'Substantial Completion Notification drafted to Owner and Architect: "The Work is substantially complete as defined in AIA Document A201 Section 9.8. Contractor requests the Architect conduct an inspection and issue a Certificate of Substantial Completion. Attached herewith is Contractor''s punch list of items remaining for final completion. Commencement of the one-year correction period is hereby requested effective the date of the Certificate."', true),
  ('doc_drafting', 'construction', 'lien_waiver_draft', 8, 'Draft a lien waiver document', 'Conditional Waiver and Release on Progress Payment drafted per your state''s statutory form requirements. Document includes: claimant name, owner name, project name and address, through-date, payment amount, and conditional release language. This waiver becomes effective only upon actual receipt and clearance of the referenced payment. Notarization block included per your state statute.', true),
  ('doc_drafting', 'construction', 'bid_bond_letter', 9, 'Draft a bid bond transmittal', 'Bid Bond transmittal letter drafted to accompany your bonding company''s AIA A310: "Enclosed please find the Bid Bond in the amount of 5% of the total bid price as required by the Instructions to Bidders for the Central Fire Station Replacement project. Should our firm be the apparent low bidder, we confirm the ability to provide Performance and Payment Bonds per AIA A312 within 10 days of Notice of Award."', true),
  ('doc_drafting', 'construction', 'get_started', 10, 'Start drafting in seconds, not hours', 'Your PMs and supers spend hours every week writing the same types of letters, notices, and proposals. Our AI drafts construction documents in seconds using your project data — consistent, contract-compliant, and professional every time. From change orders to closeout, we''ve got every document covered. Start your free trial and draft your first 10 documents at no cost.', true),

  ('marketing_engine', 'construction', 'welcome', 1, 'Start conversation', 'Welcome to your construction marketing intelligence engine. I help GCs and specialty contractors build compelling qualification packages, project experience profiles, and pursuit strategies that win work. Whether you''re targeting public sector CM-at-risk, negotiated GMP, or design-build pursuits, I''ll help you present your firm''s best case. What pursuit are you working on?', true),
  ('marketing_engine', 'construction', 'project_profile', 2, 'Build a project experience profile', 'Project profile drafted for Northgate Distribution Center: 340,000 SF tilt-up concrete facility, $28.4M GMP, delivered 23 days ahead of schedule. Highlights include: self-performed concrete and structural steel erection, zero OSHA recordables in 18 months, $6.2M in local subcontractor participation, and LEED Silver certification. Formatted for SOQ submittal with owner, architect, and reference contact details populated.', true),
  ('marketing_engine', 'construction', 'qualifications_package', 3, 'Generate a qualifications package', 'SOQ generated for the Riverside Unified School District new middle school pursuit. Package includes your firm overview, relevant K-12 education project experience (8 comparable projects, $180M total value), DSA inspection process narrative, key personnel bios with certifications, safety record (0.8 TRIR over 3 years), bonding capacity letter placeholder, and MBE/WBE subcontracting commitment. 24 pages formatted to district requirements.', true),
  ('marketing_engine', 'construction', 'bid_strategy', 4, 'Develop a bid strategy', 'For the $45M municipal justice center hard bid, your win strategy should focus on three differentiators: your firm''s prior detention facility experience (2 comparable projects within 5 years), your self-perform concrete capability eliminating the single largest bid risk, and your local workforce commitment — the city council has prioritized local hire in their procurement policy. Lead with these in your cover letter and preconstruction narrative.', true),
  ('marketing_engine', 'construction', 'case_study_generation', 5, 'Write a project case study', 'Case study drafted for the Highland Hospital Expansion: "When unforeseen site conditions threatened the schedule and budget of a $67M occupied hospital addition, our team''s proactive RFI resolution and change order management delivered the project on time and within 1.2% of the original GMP. Zero patient care disruptions, 100% ICRA compliance throughout construction, and a TRIR of 0.6 set a new standard for our healthcare portfolio."', true),
  ('marketing_engine', 'construction', 'sub_outreach_campaign', 6, 'Create a subcontractor outreach campaign', 'DBE/MBE/WBE subcontractor outreach campaign drafted for your transit authority pursuit. Campaign includes: outreach letters to 34 certified firms in target trades (concrete, electrical, mechanical, specialty coatings), pre-bid meeting invitation with scope breakout schedule, good faith effort documentation template, and follow-up sequence. Compliance with the owner''s 25% DBE participation goal is documented throughout.', true),
  ('marketing_engine', 'construction', 'award_submission', 7, 'Draft an industry award submission', 'AGC Build America Award submission drafted for the Eastport Bridge Replacement: project narrative emphasizes innovative accelerated bridge construction (ABC) methodology, 54-hour traffic closure versus the industry norm of 6 months, $2.1M in cost savings versus the traditional approach, and zero safety incidents across 280,000 worker hours. Supporting data tables and photo captions formatted per AGC submission guidelines.', true),
  ('marketing_engine', 'construction', 'linkedin_content', 8, 'Generate LinkedIn content for our firm', 'LinkedIn post drafted: "Our team just topped out the 22-story Midtown Residential Tower — 847 units, 312,000 square feet, and 14 months of exceptional teamwork by our GC crew and 34 subcontractor partners. From the first concrete pour to the final steel connection, this project was a masterclass in schedule management, BIM coordination, and safety excellence. Here''s what it took. #Construction #GCLife #ToppingOut #BuildingTheFuture"', true),
  ('marketing_engine', 'construction', 'rfp_response', 9, 'Outline an RFP response strategy', 'For the $120M Convention Center Expansion RFP, your response strategy should address the four evaluation criteria in weighted order: technical approach (35%) — lead with your BIM execution plan and phasing strategy for occupied facility; relevant experience (30%) — feature 3 convention/hospitality projects over $80M; key personnel (20%) — your proposed PM has led 2 comparable projects; and price/fee (15%) — target a competitive CM fee given the procurement history.', true),
  ('marketing_engine', 'construction', 'get_started', 10, 'Win more work with better marketing', 'The best-built firm doesn''t always win — the best-presented firm does. Our marketing engine helps construction firms tell their story compellingly across SOQs, RFP responses, case studies, and digital content. Stop losing pursuits to competitors with weaker portfolios but better presentations. Book a pursuit strategy session and let''s build your winning proposal together.', true)
ON CONFLICT (demo_type, vertical, trigger_key) DO UPDATE SET
  sequence_order = EXCLUDED.sequence_order,
  prompt_text = EXCLUDED.prompt_text,
  response_text = EXCLUDED.response_text,
  active = EXCLUDED.active;

-- =============================================================================
-- Property Management vertical — 70 demo_cached_responses (7 demos × 10 each)
-- =============================================================================
INSERT INTO demo_cached_responses (demo_type, vertical, trigger_key, sequence_order, prompt_text, response_text, active) VALUES
  ('chatbot', 'property_mgmt', 'welcome', 1, 'Start conversation', 'Welcome to your AI-powered property management assistant! I can help you with lease questions, tenant screening, maintenance requests, HAP payments, and more. What would you like to work on today?', true),
  ('chatbot', 'property_mgmt', 'maintenance_request', 2, 'I have a maintenance issue', 'I''ve logged your maintenance request and assigned it a work order number. Our system will automatically notify the appropriate vendor based on the issue type — HVAC, plumbing, or electrical. You can track the status in real time through the tenant portal.', true),
  ('chatbot', 'property_mgmt', 'rent_payment', 3, 'When is rent due?', 'Rent is due on the 1st of each month with a 5-day grace period before late fees apply. You can pay online via ACH, credit card, or money order at the office. Your current ledger balance and payment history are always available in your tenant portal.', true),
  ('chatbot', 'property_mgmt', 'lease_renewal', 4, 'I want to renew my lease', 'Great news — your unit is eligible for renewal! I''ve pulled your current lease terms and can show you the proposed renewal rate based on market comps and your on-time payment history. Would you like me to send the renewal offer to your email for e-signature?', true),
  ('chatbot', 'property_mgmt', 'section8_question', 5, 'I have a Section 8 voucher', 'We participate in the Housing Choice Voucher Program and welcome Section 8 tenants. Once your voucher is verified, we''ll coordinate with your housing authority for the HAP contract and inspection scheduling. Fair housing laws ensure your application is evaluated on equal criteria.', true),
  ('chatbot', 'property_mgmt', 'move_out_inquiry', 6, 'I want to move out', 'I''m sorry to see you go! To begin the move-out process, I''ll need your intended vacate date — please provide at least 30 days'' written notice per your lease terms. We''ll schedule a pre-move-out inspection and send you a security deposit disposition within 21 days of vacancy.', true),
  ('chatbot', 'property_mgmt', 'tenant_screening', 7, 'How does tenant screening work?', 'Our screening process checks credit, rental history, income verification, and criminal background in compliance with fair housing guidelines. We require gross monthly income of at least 3x the rent and a minimum credit score of 600. Results are typically returned within 24 hours of a completed application.', true),
  ('chatbot', 'property_mgmt', 'noise_complaint', 8, 'I want to file a noise complaint', 'I''ve recorded your noise complaint and will send a courtesy notice to the unit in question per our lease enforcement policy. If the issue persists, a formal lease violation notice will be issued. Please document any recurring incidents with dates and times to support the case file.', true),
  ('chatbot', 'property_mgmt', 'security_deposit', 9, 'What happens to my security deposit?', 'Your security deposit is held in a separate escrow account as required by state law. Deductions may be made for damages beyond normal wear and tear, unpaid rent, or lease violations. A full itemized statement will be mailed within the legally required timeframe after your move-out inspection.', true),
  ('chatbot', 'property_mgmt', 'get_started', 10, 'How do I get started?', 'Ready to experience smarter property management? Schedule a live demo with our team to see how AI-driven workflows can reduce vacancy, automate rent collection, and streamline HAP processing across your entire portfolio. Click below to book a 30-minute walkthrough!', true),

  ('analytics', 'property_mgmt', 'welcome', 1, 'Start conversation', 'Welcome to your property management analytics dashboard. I can surface insights on occupancy rates, NOI trends, rent roll performance, cap rates, and unit turnover across your entire portfolio. What metrics would you like to explore?', true),
  ('analytics', 'property_mgmt', 'occupancy_report', 2, 'Show me occupancy rates', 'Your portfolio-wide occupancy rate is currently 94.2%, up 1.8 points quarter-over-quarter. Your top-performing properties are running at 97–98% occupancy while two assets show elevated vacancy risk driven by above-market renewal rates. Drilling down by unit type reveals 2-bedrooms have the tightest availability at 96.8%.', true),
  ('analytics', 'property_mgmt', 'noi_analysis', 3, 'Analyze my NOI', 'Net Operating Income across your portfolio increased 6.3% year-over-year, driven by a 4.1% average rent increase and a 12% reduction in maintenance costs through preventive work order programs. Rising insurance premiums and utility expenses partially offset gains, compressing margins by approximately 80 basis points.', true),
  ('analytics', 'property_mgmt', 'rent_roll_summary', 4, 'Pull the rent roll summary', 'Your current rent roll shows $2.4M in scheduled monthly gross rents with a 97.1% collection rate. Delinquency is concentrated in 14 units across three properties, totaling $38,400 in outstanding balances. HAP payments account for 22% of total collections and arrived on time in 11 of 12 months this year.', true),
  ('analytics', 'property_mgmt', 'cap_rate_benchmark', 5, 'What are my cap rates?', 'Your stabilized assets are trading at an average implied cap rate of 5.4%, consistent with comparable Class B multifamily in your submarkets. Value-add properties in lease-up are currently reflecting a 4.1% going-in cap rate with a projected stabilized cap of 6.2% upon full occupancy.', true),
  ('analytics', 'property_mgmt', 'turnover_analysis', 6, 'Show turnover analysis', 'Portfolio unit turnover averaged 28% over the trailing 12 months, slightly above the 25% industry benchmark. Average days-vacant per turn is 18 days, costing an estimated $1,950 per unit in lost rent. Properties with proactive 90-day renewal outreach programs show 34% lower turnover rates.', true),
  ('analytics', 'property_mgmt', 'maintenance_spend', 7, 'Analyze maintenance spend', 'Total maintenance and repair spend was $184,000 over the last 12 months, averaging $312 per unit. HVAC and plumbing account for 61% of all work order costs. Predictive maintenance flagging has reduced emergency service calls by 23%, and vendor invoice cycle time is down to an average of 4.2 days.', true),
  ('analytics', 'property_mgmt', 'section8_compliance', 8, 'HAP and Section 8 performance', 'You currently manage 87 Section 8 units with an average HAP payment of $1,140 per month. RFTA approval rates are at 94% and all HQS inspections passed on the first attempt for 89% of units this year. Tracking HAP abatement risk early has prevented an estimated $27,000 in lost subsidy payments.', true),
  ('analytics', 'property_mgmt', 'delinquency_trend', 9, 'Delinquency and collections trend', 'Month-end delinquency has trended down from 4.8% to 2.9% over the past six months following the rollout of automated payment reminders and ACH enrollment campaigns. Units with active eviction filings represent 0.7% of the portfolio, and 62% of those accounts made partial payment after notice was served.', true),
  ('analytics', 'property_mgmt', 'get_started', 10, 'How do I get started?', 'See how data-driven property management can maximize your portfolio''s NOI and reduce vacancy loss. Book a personalized analytics demo today and we''ll map your current KPIs against top-quartile benchmarks — so you know exactly where the opportunity is. Schedule your session now!', true),

  ('email_sms', 'property_mgmt', 'welcome', 1, 'Start conversation', 'Welcome to your automated resident communications hub. I can generate lease renewal offers, maintenance updates, delinquency notices, inspection reminders, and HAP-related correspondence — all personalized and compliant with fair housing standards. What would you like to send today?', true),
  ('email_sms', 'property_mgmt', 'rent_reminder', 2, 'Send rent reminder', 'Subject: Friendly Reminder — Rent Due on the 1st. Hi [Tenant Name], just a quick reminder that your rent payment of $[Amount] is due on [Date]. Pay securely online via your tenant portal to avoid a late fee after the 5-day grace period. Thank you for being a valued resident!', true),
  ('email_sms', 'property_mgmt', 'lease_renewal_offer', 3, 'Send lease renewal offer', 'Subject: Your Lease Renewal Offer is Ready! Dear [Tenant Name], we''d love to have you stay another year at [Property Name]. Your new monthly rate would be $[Amount], reflecting current market conditions in your area. Please review and sign your renewal agreement by [Date] to lock in this rate.', true),
  ('email_sms', 'property_mgmt', 'maintenance_update', 4, 'Send maintenance status update', 'Hi [Tenant Name], your maintenance request #[WO Number] for [Issue Type] has been assigned to [Vendor Name] and is scheduled for [Date/Time]. Please ensure someone 18 or older is present to provide access. We appreciate your patience and will follow up once the work is complete.', true),
  ('email_sms', 'property_mgmt', 'delinquency_notice', 5, 'Send delinquency notice', 'Subject: Important — Outstanding Balance on Your Account. Dear [Tenant Name], our records show a past-due balance of $[Amount] as of [Date]. Please remit payment immediately to avoid further action, including a formal Pay or Quit notice. Contact our office at [Phone] if you need to discuss a payment arrangement.', true),
  ('email_sms', 'property_mgmt', 'inspection_notice', 6, 'Send inspection notice', 'Dear [Tenant Name], we will be conducting a routine property inspection of your unit at [Address] on [Date] between [Time Window]. This inspection ensures your home meets habitability standards and satisfies HQS requirements for your Housing Choice Voucher. Please notify us if you need to reschedule.', true),
  ('email_sms', 'property_mgmt', 'move_in_instructions', 7, 'Send move-in instructions', 'Welcome home, [Tenant Name]! Your keys will be ready for pickup at our office on [Date] after 10 AM. Please bring a valid photo ID and certified funds for your security deposit if not already paid. Your move-in inspection checklist is attached — complete and return it within 72 hours to document the unit''s condition.', true),
  ('email_sms', 'property_mgmt', 'eviction_warning', 8, 'Send eviction warning communication', 'NOTICE TO PAY RENT OR QUIT: [Tenant Name], you are hereby notified that rent totaling $[Amount] remains unpaid as of [Date]. You must pay the full amount or vacate the premises within [X] days as required by [State] law. Failure to comply may result in unlawful detainer proceedings. This notice is served in accordance with your lease agreement.', true),
  ('email_sms', 'property_mgmt', 'hap_voucher_welcome', 9, 'Welcome new Section 8 tenant', 'Dear [Tenant Name], we are pleased to confirm your Housing Choice Voucher has been accepted for unit [Address]. Your HAP contract has been submitted to [Housing Authority], and your portion of the rent is $[Amount] due on the 1st of each month. We look forward to welcoming you as a resident!', true),
  ('email_sms', 'property_mgmt', 'get_started', 10, 'How do I get started?', 'Automate every resident touchpoint — from lease-up to move-out — with compliant, personalized messaging that saves your team hours every week. Let us show you how our communication engine integrates with your existing property management software. Book your free demo today!', true),

  ('doc_processing', 'property_mgmt', 'welcome', 1, 'Start conversation', 'Welcome to AI-powered document processing for property management. I can extract, classify, and validate lease agreements, HAP contracts, inspection reports, vendor invoices, tenant applications, and rent rolls in seconds. What documents would you like to process today?', true),
  ('doc_processing', 'property_mgmt', 'lease_extraction', 2, 'Extract data from lease', 'I''ve extracted the key data points from the uploaded lease: tenant name, unit address, monthly rent of $1,450, lease start/end dates, security deposit amount, pet addendum status, and late fee schedule. All fields have been validated against your lease template and flagged discrepancies are highlighted for review.', true),
  ('doc_processing', 'property_mgmt', 'hap_contract_processing', 3, 'Process HAP contract', 'The HAP contract has been processed and all critical fields extracted: Housing Authority name, contract unit, assisted monthly rent, HAP payment amount, tenant rent portion, and effective dates. The contract has been cross-referenced against the current utility allowance schedule and is ready for countersignature.', true),
  ('doc_processing', 'property_mgmt', 'invoice_processing', 4, 'Process vendor invoices', 'I''ve processed 14 vendor invoices totaling $22,840. Each invoice has been matched to its corresponding work order, property, and GL account code. Three invoices flagged potential discrepancies: one duplicate submission, one amount exceeding the approved bid, and one missing unit number for cost allocation.', true),
  ('doc_processing', 'property_mgmt', 'tenant_application', 5, 'Process tenant application', 'The rental application has been fully extracted and scored. Income-to-rent ratio is 3.4x, credit score returned at 672, and no prior eviction records found. The application meets your stated minimum criteria and is ready to advance to the next stage. Shall I trigger the background and credit check authorization workflow?', true),
  ('doc_processing', 'property_mgmt', 'inspection_report', 6, 'Process inspection report', 'The move-out inspection report has been digitized and 23 line-item conditions extracted. Items flagged as chargeable damages (beyond normal wear and tear) total an estimated $1,240 in repair costs. The report has been linked to the tenant''s security deposit record and is ready for disposition letter generation.', true),
  ('doc_processing', 'property_mgmt', 'rent_roll_import', 7, 'Import rent roll document', 'Your uploaded rent roll has been parsed — 148 units extracted with rent amounts, lease expirations, tenant names, HAP subsidy amounts, and vacancy status. Eight units show lease expiration dates within 60 days and have been flagged for renewal outreach. The data is ready to sync with your property management system.', true),
  ('doc_processing', 'property_mgmt', 'eviction_docs', 8, 'Process eviction filing documents', 'The eviction packet has been reviewed: Pay or Quit notice, proof of service, and ledger statement all present and properly dated. I''ve verified compliance with [State] statutory notice periods and identified the proper court filing jurisdiction. The packet is ready for attorney review or self-represented filing.', true),
  ('doc_processing', 'property_mgmt', 'security_deposit_disposition', 9, 'Generate deposit disposition', 'The security deposit disposition has been drafted based on the move-out inspection, final account ledger, and applicable state law deduction limits. Total deductions of $875 have been itemized across cleaning, carpet repair, and unpaid rent. The refund amount and itemization letter are ready for mailing within the statutory deadline.', true),
  ('doc_processing', 'property_mgmt', 'get_started', 10, 'How do I get started?', 'Stop manually entering data from leases, invoices, and inspection reports. Our document AI processes property management paperwork with 99.2% field accuracy and integrates directly with Yardi, AppFolio, and Buildium. Schedule a document processing pilot with your own files and see the ROI firsthand.', true),

  ('competitive_analysis', 'property_mgmt', 'welcome', 1, 'Start conversation', 'Welcome to competitive market analysis for property management. I can benchmark your portfolio against local comps on rent rates, occupancy, amenities, cap rates, and operational efficiency. Which market or asset class would you like to analyze today?', true),
  ('competitive_analysis', 'property_mgmt', 'rent_comp_analysis', 2, 'Compare our rents to the market', 'Your average effective rent of $1,380 per unit is approximately 4.2% below the submarket median of $1,439. Competing Class B properties within a one-mile radius are achieving $1,410–$1,470 for comparable unit types, suggesting measured rent growth potential on upcoming renewals and lease-up units without sacrificing occupancy.', true),
  ('competitive_analysis', 'property_mgmt', 'occupancy_benchmarking', 3, 'Benchmark our occupancy', 'Your portfolio occupancy of 94.2% trails the submarket average of 95.8% by 160 basis points. The gap is largely attributable to two assets with above-average turnover and slower lease-up velocity. Your top-performing properties match or exceed submarket benchmarks, indicating operational best practices worth scaling.', true),
  ('competitive_analysis', 'property_mgmt', 'cap_rate_market_scan', 4, 'What are market cap rates?', 'Class B multifamily in your target submarkets is trading at 5.0–5.6% cap rates, with value-add deals attracting the most investor competition. Your implied cap rate of 5.4% is well-positioned relative to market. Recent comparable sales suggest buyers are underwriting 3–4% annual rent growth, which supports continued NOI expansion in your portfolio.', true),
  ('competitive_analysis', 'property_mgmt', 'amenity_gap_analysis', 5, 'Analyze amenity gaps', 'Competitors in your market are increasingly offering in-unit washer/dryer connections, package lockers, and online maintenance portals — features now expected by 78% of prospective renters surveyed. Your properties currently lack package locker facilities, which is cited as a differentiating factor by three of your top five comps.', true),
  ('competitive_analysis', 'property_mgmt', 'section8_market_share', 6, 'Compare Section 8 acceptance rates', 'Approximately 34% of rental properties in your submarket accept Housing Choice Vouchers, versus your portfolio rate of 22%. Properties that actively market HAP participation report 18% faster lease-up for affordable units and benefit from more stable, government-backed income streams that reduce delinquency risk during economic downturns.', true),
  ('competitive_analysis', 'property_mgmt', 'turnover_benchmarking', 7, 'How does our turnover compare?', 'Your 28% annual turnover rate exceeds the regional benchmark of 23% for similar asset classes. Each additional turnover costs an estimated $3,200 in make-ready, vacancy loss, and leasing commissions. Competing operators with sub-20% turnover rates consistently invest in proactive renewal programs, resident events, and faster maintenance response times.', true),
  ('competitive_analysis', 'property_mgmt', 'fair_housing_risk_scan', 8, 'Fair housing compliance benchmarking', 'A scan of recent HUD enforcement actions in your market shows a 31% increase in fair housing complaints over the past 18 months, concentrated around source-of-income discrimination and accessibility accommodations. Your current screening criteria and advertising language should be reviewed against AFFH guidelines to ensure full compliance and minimize exposure.', true),
  ('competitive_analysis', 'property_mgmt', 'property_mgmt_software_landscape', 9, 'What software are competitors using?', 'Market leaders in your region predominantly use Yardi Voyager or AppFolio, with 67% having adopted AI-assisted leasing tools in the last two years. Operators using automated rent optimization software report 2.1% higher effective rents and 15% faster lease execution compared to manual pricing methods.', true),
  ('competitive_analysis', 'property_mgmt', 'get_started', 10, 'How do I get started?', 'Know exactly where you stand against the competition — on rents, occupancy, cap rates, and operational efficiency. Our market intelligence platform gives property managers and owners a continuous competitive edge. Request a custom competitive report for your portfolio today.', true),

  ('doc_drafting', 'property_mgmt', 'welcome', 1, 'Start conversation', 'Welcome to AI-assisted document drafting for property management. I can draft leases, addenda, eviction notices, HAP correspondence, vendor contracts, inspection letters, and fair housing policies — all tailored to your jurisdiction and property. What would you like to create today?', true),
  ('doc_drafting', 'property_mgmt', 'lease_agreement', 2, 'Draft a lease agreement', 'I''ve drafted a residential lease agreement for [Unit Address] incorporating your standard terms: 12-month term, $1,425/month rent, $1,425 security deposit, no-smoking addendum, and pet policy rider. All clauses have been reviewed for compliance with [State] landlord-tenant law, including required disclosures and habitability standards.', true),
  ('doc_drafting', 'property_mgmt', 'pay_or_quit_notice', 3, 'Draft a Pay or Quit notice', 'The 3-Day Notice to Pay Rent or Quit has been drafted for Tenant [Name] at [Unit Address], reflecting an outstanding balance of $[Amount] through [Date]. The notice includes the legally required payment instructions, cure deadline, and delivery certification. Please confirm the notarization or proof-of-service method required in your jurisdiction before serving.', true),
  ('doc_drafting', 'property_mgmt', 'hap_correspondence', 4, 'Draft HAP correspondence', 'I''ve drafted a letter to [Housing Authority] requesting an annual rent increase adjustment for [Unit Address] under the HAP contract. The letter references the current contract rent, proposed new rent, market comparables, and required 60-day advance notice. It is formatted per HUD correspondence guidelines and ready for your signature.', true),
  ('doc_drafting', 'property_mgmt', 'pet_addendum', 5, 'Draft a pet addendum', 'The Pet Addendum has been drafted permitting one dog up to 35 lbs at [Unit Address], with a non-refundable pet fee of $300 and a monthly pet rent of $50. The addendum includes liability, damage responsibility, and noise clauses, and clearly distinguishes between pets and HUD-protected assistance animals to ensure fair housing compliance.', true),
  ('doc_drafting', 'property_mgmt', 'vendor_contract', 6, 'Draft a vendor service contract', 'The maintenance service agreement with [Vendor Name] has been drafted for HVAC preventive maintenance across 12 units at [Property Name]. The contract specifies service frequency, response time SLAs, insurance and indemnification requirements, and termination provisions. Certificate of insurance requirements are included per your standard vendor onboarding policy.', true),
  ('doc_drafting', 'property_mgmt', 'fair_housing_policy', 7, 'Draft a fair housing policy', 'I''ve drafted a Fair Housing and Equal Opportunity Policy for [Company Name] covering protected classes under federal, state, and local law, including source-of-income protections where applicable. The policy addresses advertising standards, tenant screening criteria, reasonable accommodation and modification procedures, and staff training requirements.', true),
  ('doc_drafting', 'property_mgmt', 'security_deposit_letter', 8, 'Draft security deposit return letter', 'The Security Deposit Disposition Letter for [Tenant Name] has been drafted, itemizing deductions of $[Amount] for [specific items] and reflecting a refund of $[Remaining Balance]. The letter cites applicable state law, includes the required itemization format, and has been dated to comply with the statutory return deadline. Ready for mailing via certified mail.', true),
  ('doc_drafting', 'property_mgmt', 'lease_renewal_letter', 9, 'Draft lease renewal letter', 'The Lease Renewal Offer Letter for [Tenant Name] has been drafted offering a 12-month renewal at $[New Rate], representing a $[Increase] increase over the current rent. The letter highlights resident retention incentives, requires a response by [Date], and includes a pre-populated renewal addendum for e-signature. A month-to-month fallback rate is also included.', true),
  ('doc_drafting', 'property_mgmt', 'get_started', 10, 'How do I get started?', 'Draft legally sound leases, notices, and compliance documents in minutes — not hours. Our AI document drafting engine is trained on property management law across all 50 states and integrates with your existing workflows. Start your free trial today and generate your first lease in under 60 seconds.', true),

  ('marketing_engine', 'property_mgmt', 'welcome', 1, 'Start conversation', 'Welcome to your AI marketing engine for property management. I can create compelling vacancy listings, social media content, email campaigns, ILS copy, and paid ad creative to fill units faster and build your brand. What would you like to market today?', true),
  ('marketing_engine', 'property_mgmt', 'vacancy_listing', 2, 'Create a vacancy listing', 'Spacious 2BR/1BA apartment at [Property Name] — now available! Enjoy updated kitchen appliances, in-unit washer/dryer hookups, and ample closet space. Located minutes from [Landmark/Transit], with easy access to shopping and dining. Professionally managed with an online tenant portal for easy rent payments and maintenance requests. Housing Choice Vouchers welcome. Call today!', true),
  ('marketing_engine', 'property_mgmt', 'social_media_post', 3, 'Write social media posts', 'Your dream home is waiting! Our newly renovated 1BR units at [Property Name] feature modern finishes, updated fixtures, and a resident portal for 24/7 maintenance requests. Occupancy is filling up fast — tour today and ask about our move-in special. We proudly accept Section 8 vouchers and comply with all fair housing laws. [Link] #ApartmentHunting #PropertyManagement', true),
  ('marketing_engine', 'property_mgmt', 'email_campaign', 4, 'Write a lease-up email campaign', 'Subject: Limited Units Remaining at [Property Name] — Don''t Miss Out! We have just a few units left at [Property Name] and they''re going fast. Qualified renters can enjoy [amenity highlights], easy online applications, and a responsive management team. Housing Choice Vouchers accepted. Apply today and move in within [X] days — no hassle, no delays.', true),
  ('marketing_engine', 'property_mgmt', 'paid_ad_copy', 5, 'Create Google/Meta ad copy', 'Headline: Affordable Apartments — Vouchers Welcome | [City, State]. Body: Find your next home at [Property Name]. Spacious units, online rent payment, responsive maintenance team. Apply online in minutes. Income-based housing available. Fair housing laws observed. Call [Phone] or visit [URL] to schedule your tour today. Limited availability.', true),
  ('marketing_engine', 'property_mgmt', 'referral_program_promo', 6, 'Write a resident referral promotion', 'Love living at [Property Name]? Refer a friend and earn $[Amount] off your next month''s rent when they sign a 12-month lease! Your referral must complete a full tenant screening, execute a lease, and take occupancy to qualify. There''s no limit to how many friends you can refer — the more you share, the more you save. See the leasing office for full details.', true),
  ('marketing_engine', 'property_mgmt', 'reputation_management', 7, 'Draft review response templates', 'Thank you so much for your feedback, [Resident Name]! We''re thrilled to hear you''ve had a positive experience at [Property Name]. Our team works hard to maintain a well-managed, welcoming community for all residents. If there''s anything more we can do to make your home even better, please don''t hesitate to reach out to the management office directly.', true),
  ('marketing_engine', 'property_mgmt', 'seasonal_campaign', 8, 'Create a seasonal leasing campaign', 'Spring into your new home at [Property Name]! With peak moving season here, now is the perfect time to lock in your new apartment. We''re offering waived application fees and a $[Amount] gift card for leases signed before [Date]. Don''t wait — our occupancy historically reaches 98% by June. Tour today and see why residents love calling [Property Name] home.', true),
  ('marketing_engine', 'property_mgmt', 'ils_optimization', 9, 'Optimize ILS listings', 'Your Zillow and Apartments.com listings have been updated with high-impact keywords: pet-friendly, in-unit laundry, HCV/Section 8 accepted, online payments, and professional management. Photos have been sequenced to lead with the most appealing spaces. Listings now include a virtual tour link and show average days-on-market of 8 versus a submarket average of 19.', true),
  ('marketing_engine', 'property_mgmt', 'get_started', 10, 'How do I get started?', 'Fill vacancies faster and build a brand that attracts quality residents — without hiring a marketing agency. Our AI marketing engine creates ILS listings, ad copy, email campaigns, and social content tailored to your properties in minutes. Schedule a demo and see your first AI-generated listing live before the call ends.', true)
ON CONFLICT (demo_type, vertical, trigger_key) DO UPDATE SET
  sequence_order = EXCLUDED.sequence_order,
  prompt_text = EXCLUDED.prompt_text,
  response_text = EXCLUDED.response_text,
  active = EXCLUDED.active;

-- =============================================================================
-- Legal vertical — 70 demo_cached_responses (7 demos × 10 each)
-- Every response includes mandatory disclaimer per vertical config
-- =============================================================================
INSERT INTO demo_cached_responses (demo_type, vertical, trigger_key, sequence_order, prompt_text, response_text, active) VALUES
  ('chatbot', 'legal', 'welcome', 1, 'Start conversation', 'Welcome to your AI-powered legal practice assistant. I can help you manage client intake, matter tracking, court deadlines, and billing inquiries across your firm. Whether you handle estate planning, litigation, or transactional work, I''m here to streamline your workflow. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('chatbot', 'legal', 'client_intake', 2, 'New client inquiry', 'I can guide new clients through your intake process, collecting matter type, jurisdiction, opposing parties, and conflict-check information before their first consultation. All data is securely stored and routed to your matter management system for attorney review. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('chatbot', 'legal', 'retainer_inquiry', 3, 'Ask about retainer fees', 'Retainer agreements at this firm are tailored to the scope and complexity of each matter. For litigation matters, a standard retainer is drawn against billable hours tracked in the firm''s timekeeping system, with replenishment notices sent automatically when the balance falls below threshold. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('chatbot', 'legal', 'iolta_question', 4, 'Ask about trust account', 'Client funds held in advance of earned fees are deposited into the firm''s IOLTA account, fully segregated from operating funds per state bar regulations. You will receive a trust ledger statement monthly showing all deposits, disbursements, and current balance attributed to your matter. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('chatbot', 'legal', 'deadline_check', 5, 'Check upcoming deadlines', 'Your matter currently has three upcoming court deadlines: a discovery response due in 14 days, a motion hearing scheduled in 21 days, and a pre-trial conference in 45 days. All deadlines are calendared in the docketing system with 7-day and 24-hour automated reminders sent to the assigned attorney. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('chatbot', 'legal', 'discovery_status', 6, 'Ask about discovery progress', 'Document production for the pending discovery requests is 72% complete, with 3,400 documents reviewed and 820 flagged as responsive. Privilege review is ongoing and a privilege log is being compiled for submission alongside the production set. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('chatbot', 'legal', 'billing_inquiry', 7, 'Ask about invoice', 'Your most recent invoice covers 18.4 hours of attorney and paralegal time related to contract negotiation and court filing preparation. Detailed time entries are available in the client portal, and payment can be made by ACH transfer or credit card through the secure billing link attached to the invoice. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('chatbot', 'legal', 'estate_planning_faq', 8, 'Ask about estate planning services', 'The firm''s estate planning practice handles wills, revocable living trusts, irrevocable trusts, powers of attorney, and healthcare directives. We work with clients to minimize estate tax exposure, ensure smooth asset transfer, and address special needs planning where applicable. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('chatbot', 'legal', 'conflict_check', 9, 'Request conflicts check status', 'A conflicts check has been run against the firm''s matter management database, screening all named parties, related entities, and known affiliates against current and former clients. No conflicts were identified; the file has been cleared and assigned to the intake attorney for engagement letter preparation. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('chatbot', 'legal', 'get_started', 10, 'Close and CTA', 'Ready to put AI to work across your entire legal practice? From intake and conflicts through billing and post-matter archiving, our platform integrates with your existing case management and timekeeping tools. Schedule a live demonstration with our legal solutions team today to see the full workflow in action. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),

  ('analytics', 'legal', 'welcome', 1, 'Start analytics demo', 'Welcome to the legal practice analytics dashboard. Here you can monitor firm-wide KPIs including realization rates, collection rates, matter profitability, and attorney utilization across all practice groups. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('analytics', 'legal', 'realization_rate', 2, 'Show realization rates', 'Firm-wide realization rate stands at 87.3% this quarter, with the litigation group leading at 91.2% and the transactional group at 84.6%. Matters with fixed-fee arrangements are excluded from realization calculations and tracked separately under alternative fee arrangement reporting. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('analytics', 'legal', 'collection_trends', 3, 'Show collection trends', 'Collections are up 6.4% year-over-year, with average days-to-payment decreasing from 52 to 44 days following implementation of automated invoice reminders and online payment options. Outstanding receivables over 90 days have decreased by 18% compared to the same period last year. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('analytics', 'legal', 'matter_profitability', 4, 'Analyze matter profitability', 'Estate planning matters generate the highest average profit margin at 64%, followed by corporate transactional work at 58% and commercial litigation at 41%. Contingency fee litigation shows variable profitability with a trailing 24-month average of 71% on settled matters. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('analytics', 'legal', 'timekeeping_compliance', 5, 'Check timekeeping compliance', 'Timekeeping compliance across the firm stands at 93%, with 7% of billable hours entered more than 48 hours after the work was performed. Late entry is most prevalent among partners with heavy court schedules; automated same-day entry reminders have been enabled for those timekeepers. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('analytics', 'legal', 'iolta_reconciliation', 6, 'Trust account reconciliation summary', 'All IOLTA sub-ledgers reconciled to the pooled trust bank statement as of month-end with zero variance. Twenty-three client trust sub-accounts are active; the largest balance relates to a pending real estate closing held in escrow pending title clearance. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('analytics', 'legal', 'docketing_compliance', 7, 'Docketing deadline compliance', 'Court deadline compliance is 99.1% over the trailing 12 months, with two missed deadlines both attributed to opposing-counsel-confirmed extensions that were not reflected in the docketing system in time. Corrective workflow updates have been deployed requiring attorney confirmation before any court date is modified. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('analytics', 'legal', 'headcount_utilization', 8, 'Attorney utilization report', 'Associate utilization averaged 1,742 billable hours annualized this quarter, against a firm target of 1,800. Three associates are tracking below 85% of target and have been flagged for workload review; two senior partners are exceeding capacity thresholds and may require delegation support. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('analytics', 'legal', 'client_concentration', 9, 'Client concentration risk', 'The top 10 clients represent 38% of total firm revenue, with the single largest client accounting for 9.2%. Concentration risk is within acceptable thresholds per firm policy, but the business development committee has set a target of reducing the top-client share below 7% through new client acquisition over the next 18 months. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('analytics', 'legal', 'get_started', 10, 'Close and CTA', 'These analytics are just the beginning of what our platform surfaces for legal practice leaders. Connect your billing, case management, and court docketing systems for a unified performance view that drives smarter resourcing and growth decisions. Book your personalized analytics walkthrough with our legal team today. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),

  ('email_sms', 'legal', 'welcome', 1, 'Start email/SMS demo', 'Welcome to the legal practice communications hub. This platform automates client-facing emails and SMS messages for matter updates, deadline reminders, invoice notifications, and appointment confirmations while maintaining compliance with professional responsibility rules. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('email_sms', 'legal', 'appointment_reminder', 2, 'Send appointment reminder', 'This is a reminder that you have a consultation scheduled with the firm on [DATE] at [TIME]. Please bring a valid photo ID, any relevant contracts or correspondence, and a completed intake questionnaire. Reply CONFIRM to confirm or call our office to reschedule. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('email_sms', 'legal', 'retainer_replenishment', 3, 'Send retainer replenishment notice', 'Your retainer balance has fallen below the agreed replenishment threshold of $2,500. To ensure uninterrupted representation on your matter, please remit a replenishment payment at your earliest convenience using the secure link in your client portal. Work on time-sensitive filings will continue during the replenishment period per our engagement letter. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('email_sms', 'legal', 'filing_confirmation', 4, 'Confirm court filing', 'We are pleased to confirm that your motion was electronically filed with the court today at [TIME] and assigned case number [CASE_NUMBER]. A filed-stamped copy has been uploaded to your secure client portal and is available for your review. The opposing party''s response deadline falls 21 days from today''s filing date. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('email_sms', 'legal', 'discovery_deadline_reminder', 5, 'Discovery deadline reminder', 'This is an automated reminder that your discovery responses are due in 7 days. Please review the draft responses your attorney uploaded to the client portal and provide any corrections or additional information as soon as possible. Failure to respond timely may result in court-imposed sanctions. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('email_sms', 'legal', 'invoice_notification', 6, 'Send invoice notification', 'Your monthly invoice for legal services has been generated and is available in your client portal. The current balance due is $[AMOUNT], payable within 30 days per your engagement agreement. You may pay by ACH, credit card, or wire transfer; please reference your matter number on all payments. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('email_sms', 'legal', 'trust_disbursement', 7, 'Trust disbursement notice', 'A disbursement of $[AMOUNT] has been made from your client trust account today to [PAYEE] in connection with [MATTER_DESCRIPTION]. Your updated trust ledger reflecting this transaction is attached to this email for your records. Please contact our office with any questions about this disbursement. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('email_sms', 'legal', 'hearing_reminder', 8, 'Court hearing reminder', 'You have a court hearing scheduled for [DATE] at [TIME] in [COURTROOM]. Please plan to arrive at least 30 minutes early to clear security and check in with the clerk. Your attorney will meet you in the lobby and has prepared a full briefing document available in your client portal. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('email_sms', 'legal', 'matter_closed', 9, 'Matter closed notification', 'We are writing to confirm that your matter has been formally closed in our system as of today. Your complete file, including all correspondence, filed documents, and final billing statement, will be retained electronically for seven years per our document retention policy. We appreciate your trust in our firm and welcome the opportunity to assist you with future legal needs. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('email_sms', 'legal', 'get_started', 10, 'Close and CTA', 'Automated, compliant client communications reduce missed appointments, accelerate collections, and improve client satisfaction scores across every practice area. See how our email and SMS engine integrates with your matter management and billing platforms in a live demo tailored to your firm''s workflows. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),

  ('doc_processing', 'legal', 'welcome', 1, 'Start document processing demo', 'Welcome to the AI-powered legal document processing suite. This platform ingests, classifies, extracts, and routes legal documents including pleadings, contracts, discovery productions, deeds, and trust instruments with high accuracy and full audit trails. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_processing', 'legal', 'contract_extraction', 2, 'Extract contract metadata', 'The AI extracted 14 key data points from the uploaded supply agreement including effective date, governing law, termination provisions, limitation of liability cap, and all defined party names. These data points have been auto-populated into the matter management record, reducing manual entry time by an estimated 85%. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_processing', 'legal', 'trust_document_review', 3, 'Process trust documents', 'The revocable living trust instrument has been processed and the system identified the grantor, successor trustee, beneficiaries, and asset schedule. Key provisions including distribution triggers, spendthrift clauses, and amendment procedures have been tagged and indexed for rapid retrieval during estate administration. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_processing', 'legal', 'discovery_triage', 4, 'Triage discovery production', 'A 42,000-document discovery production has been ingested, deduplicated, and classified. The AI identified 6,200 potentially responsive documents, 890 flagged for privilege review, and 312 containing key custodian names listed in the litigation hold notice. The remaining documents were classified as non-responsive with confidence scores above 94%. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_processing', 'legal', 'pleading_docketing', 5, 'Auto-docket filed pleading', 'The system automatically extracted the caption, case number, filing date, document type, and all referenced deadlines from the uploaded order and created corresponding docket entries. Three new calendar deadlines were generated and assigned to the supervising partner and responsible associate for confirmation. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_processing', 'legal', 'intake_form_processing', 6, 'Process client intake forms', 'The client intake form has been processed and all 23 data fields extracted with 99% accuracy. The system pre-populated the new matter record, generated a conflict-check query against the client and adverse party names, and routed the file to the designated intake attorney with a summary memo. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_processing', 'legal', 'deed_extraction', 7, 'Extract deed data', 'The warranty deed has been processed and key attributes extracted: grantor and grantee names, legal property description, parcel ID, recording information, and any noted easements or encumbrances. The extracted data has been mapped to the corresponding real estate matter record and flagged for title examiner review. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_processing', 'legal', 'invoice_ocr', 8, 'Process vendor invoices', 'Expert witness and court reporter invoices totaling $47,200 have been ingested via OCR, line-item costs extracted, and matched against open matter budgets. Three invoices exceeded pre-approved budget thresholds and have been flagged for partner approval before payment authorization is released. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_processing', 'legal', 'privilege_log_generation', 9, 'Generate privilege log', 'Based on attorney-reviewed privilege determinations, the system has auto-generated a formatted privilege log listing document date, author, recipients, subject matter description, and privilege basis for each of the 312 withheld documents. The log is formatted to meet the jurisdiction''s standing discovery order requirements and is ready for attorney certification. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_processing', 'legal', 'get_started', 10, 'Close and CTA', 'From discovery triage to trust instrument indexing, our document processing AI dramatically reduces the manual review burden on your attorneys and staff. Connect it to your document management system and docketing platform for an end-to-end automated pipeline. Request a scoped proof-of-concept with your own document types today. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),

  ('competitive_analysis', 'legal', 'welcome', 1, 'Start competitive analysis demo', 'Welcome to the legal market intelligence module. This tool aggregates publicly available data on competitor firms, lateral movements, client wins, verdict and settlement trends, and practice area growth signals to help your firm make informed strategic decisions. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('competitive_analysis', 'legal', 'market_positioning', 2, 'Analyze market position', 'Your firm ranks 4th in the regional market for commercial litigation by matter volume and 2nd by average matter value, indicating a strong position in high-complexity disputes. Competitors are expanding plaintiff-side mass tort practices, a segment your firm has not historically pursued but which may present referral partnership opportunities. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('competitive_analysis', 'legal', 'lateral_intelligence', 3, 'Track lateral movement', 'Three estate planning partners have moved laterally from regional competitors to national firms in the past six months, creating potential client transition opportunities in the high-net-worth estate and trust market. Proactive outreach to those partners'' former client bases may be appropriate within the bounds of professional responsibility rules. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('competitive_analysis', 'legal', 'verdict_trends', 4, 'Analyze verdict and settlement trends', 'Commercial litigation verdicts in this jurisdiction have trended 23% higher over the past two years, driven largely by increased damages awards in trade secret and non-compete matters. Plaintiff-favorable outcomes have increased in bench trials while jury trial results remain roughly even, a pattern your litigation team should factor into case strategy and settlement valuation. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('competitive_analysis', 'legal', 'practice_gap_analysis', 5, 'Identify practice area gaps', 'Analysis of competitor service offerings reveals that no firm in the local market provides dedicated ERISA compliance counsel for mid-market employers, representing an uncontested niche your firm''s benefits practice could occupy with targeted investment in one senior hire. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('competitive_analysis', 'legal', 'pricing_benchmarks', 6, 'Benchmark billing rates', 'Partner billing rates in your market range from $450 to $850 per hour for commercial litigation, with your firm positioned at the 60th percentile. Associate rates have compressed over the past 18 months as clients push for alternative fee arrangements; 34% of new matters at peer firms are now billed on fixed-fee or capped-fee structures. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('competitive_analysis', 'legal', 'client_industry_trends', 7, 'Track client industry trends', 'Regulatory enforcement activity in the healthcare and fintech sectors has increased sharply, generating significant compliance and white-collar defense work for firms with dedicated practices in those verticals. Two competitors have announced healthcare regulatory practices in the past quarter, signaling a market opportunity your firm should evaluate given existing client relationships in those industries. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('competitive_analysis', 'legal', 'referral_network_analysis', 8, 'Analyze referral network', 'Your firm receives 31% of new matters through attorney referrals, compared to a market average of 22%, indicating strong peer reputation. However, referral reciprocity analysis shows the firm refers out 2.4 matters for every one received, suggesting untapped capacity in practice areas that currently lack dedicated coverage. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('competitive_analysis', 'legal', 'technology_adoption', 9, 'Assess competitor technology adoption', 'Peer firm job postings and public announcements indicate that 6 of your 10 nearest competitors have implemented AI-assisted contract review or discovery tools in the past 18 months. Firms that have publicized these capabilities are winning more RFP responses from institutional clients who list legal technology adoption as an evaluation criterion. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('competitive_analysis', 'legal', 'get_started', 10, 'Close and CTA', 'Stay ahead of market shifts, lateral movements, and competitor positioning with continuously updated legal market intelligence built specifically for law firm leadership. Schedule a strategy session with our legal intelligence team to explore how this data can inform your firm''s growth and service expansion plans. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),

  ('doc_drafting', 'legal', 'welcome', 1, 'Start document drafting demo', 'Welcome to the AI-assisted legal document drafting workspace. This tool accelerates the preparation of engagement letters, trust instruments, litigation pleadings, discovery requests, contracts, and compliance memoranda using practice-group-specific templates enriched with current jurisdiction-specific requirements. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_drafting', 'legal', 'engagement_letter', 2, 'Draft engagement letter', 'An engagement letter has been drafted incorporating the agreed scope of representation, billing rates, retainer amount, IOLTA deposit instructions, conflict waiver language, and file retention policy. The document reflects your jurisdiction''s bar association engagement letter guidelines and includes a client acknowledgment signature block. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_drafting', 'legal', 'revocable_trust', 3, 'Draft revocable living trust', 'A revocable living trust instrument has been drafted naming the client as initial trustee with the designated successor trustee authorized to act upon incapacity or death. The trust includes pour-over provisions coordinated with the accompanying will, a spendthrift clause for beneficiary distributions, and a no-contest clause per client instruction. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_drafting', 'legal', 'demand_letter', 4, 'Draft litigation demand letter', 'A pre-litigation demand letter has been drafted asserting breach of contract claims, quantifying damages including direct losses and consequential damages within the contractual limitation of liability, and proposing a 30-day resolution period before commencement of formal proceedings. The letter is calibrated to preserve settlement leverage while establishing a clear record for subsequent litigation. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_drafting', 'legal', 'discovery_requests', 5, 'Draft discovery requests', 'A set of 25 interrogatories, 18 document requests, and 10 requests for admission has been drafted targeting the key liability and damages issues in the matter. Each request is tailored to the specific facts of the dispute and vetted against the jurisdiction''s discovery rules regarding scope, proportionality, and privilege limitations. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_drafting', 'legal', 'nda_draft', 6, 'Draft non-disclosure agreement', 'A mutual non-disclosure agreement has been drafted covering confidential information shared in connection with the proposed transaction, with a two-year term, carve-outs for publicly available information and compelled disclosures, and a return-or-destroy provision upon termination. The governing law and dispute resolution clauses have been aligned with the parties'' preferred jurisdictions. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_drafting', 'legal', 'motion_draft', 7, 'Draft motion for summary judgment', 'A motion for summary judgment has been drafted with a supporting memorandum of law citing controlling authority in the jurisdiction, a statement of undisputed material facts drawn from the evidentiary record, and proposed order. The argument is structured to address the most dispositive issue first and preemptively address the opposing party''s anticipated counter-arguments. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_drafting', 'legal', 'operating_agreement', 8, 'Draft LLC operating agreement', 'An LLC operating agreement has been drafted establishing member capital contributions, profit and loss allocation percentages, manager authority and voting thresholds, transfer restrictions with right-of-first-refusal mechanics, and buy-sell provisions triggered by death, disability, or voluntary withdrawal. The agreement includes tax distribution provisions designed to cover each member''s estimated pass-through tax liability. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_drafting', 'legal', 'compliance_memo', 9, 'Draft compliance memorandum', 'A compliance memorandum has been drafted analyzing the client''s obligations under the applicable regulatory framework, identifying three areas of current non-compliance, and recommending specific remediation steps with estimated implementation timelines. The memo is attorney-client privileged and marked accordingly; distribution should be limited to authorized personnel only. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('doc_drafting', 'legal', 'get_started', 10, 'Close and CTA', 'Cut document preparation time by up to 70% while maintaining the precision and jurisdiction-specific accuracy your clients expect. Our drafting AI learns your firm''s preferred clause libraries, formatting standards, and boilerplate preferences over time. Schedule a drafting workflow demonstration with your practice group''s document types to see it in action. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),

  ('marketing_engine', 'legal', 'welcome', 1, 'Start marketing engine demo', 'Welcome to the legal practice growth and marketing automation engine. This platform helps your firm attract, nurture, and convert prospective clients through targeted content, automated follow-up sequences, referral tracking, and ROI reporting across all marketing channels. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('marketing_engine', 'legal', 'practice_area_campaign', 2, 'Launch practice area campaign', 'An estate planning awareness campaign has been configured targeting adults aged 45 to 65 within your firm''s geographic market. The campaign includes a gated trust-and-will planning checklist as a lead magnet, a four-email nurture sequence, and a call-to-action directing prospects to book a complimentary 30-minute consultation through the firm''s online scheduling tool. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('marketing_engine', 'legal', 'referral_program', 3, 'Configure referral tracking', 'Referral tracking has been configured to attribute new matters to specific referring attorneys, financial advisors, CPAs, and former clients. Each referral source receives automated acknowledgment communications and quarterly impact reports showing matters referred, outcomes, and any applicable referral arrangement details in accordance with applicable bar rules. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('marketing_engine', 'legal', 'content_calendar', 4, 'Generate content calendar', 'A 90-day content calendar has been generated covering estate planning myth-busting articles, litigation timeline explainers, IOLTA transparency blog posts, and short-form video scripts on contract red flags for business owners. Content is mapped to target audience segments and scheduled for publication across the firm website, LinkedIn, and email newsletter cadences. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('marketing_engine', 'legal', 'lead_nurture_sequence', 5, 'Build lead nurture sequence', 'A six-touch email nurture sequence has been designed for prospective business litigation clients who download the firm''s contract dispute guide. The sequence moves from educational content on pre-litigation options to case study summaries and a final consultation offer, with branching logic that adjusts messaging based on whether the prospect opens each email. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('marketing_engine', 'legal', 'google_ads_brief', 6, 'Draft paid search campaign brief', 'A Google Ads campaign brief has been drafted targeting high-intent search terms related to estate planning attorneys, trust administration, and business contract disputes in your metro area. Recommended monthly budget, expected cost-per-click ranges, and projected consultation booking rates are included based on comparable firm benchmarks in the market. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('marketing_engine', 'legal', 'client_testimonial_workflow', 7, 'Automate testimonial collection', 'Post-matter satisfaction surveys are automatically dispatched five days after a matter is marked closed, with a follow-up request directing satisfied clients to leave a Google review or bar directory endorsement. Responses are aggregated in the marketing dashboard and flagged for attorney review before any client quote is used in firm marketing materials. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('marketing_engine', 'legal', 'seminar_promotion', 8, 'Promote client education seminar', 'A promotional campaign has been built for your upcoming estate planning seminar, including a landing page, RSVP workflow, reminder SMS sequence, and post-event follow-up emails. Attendees who do not book a consultation within 14 days of the event are automatically entered into a long-term nurture sequence delivering relevant trust and estate content monthly. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('marketing_engine', 'legal', 'roi_reporting', 9, 'Generate marketing ROI report', 'Marketing spend of $18,400 this quarter generated 94 qualified leads, 31 new client consultations, and 19 new matters with a combined estimated fee value of $214,000, representing an 11.6x return on marketing investment. Estate planning campaigns delivered the lowest cost-per-new-matter at $480, while litigation PPC campaigns averaged $2,100 per new matter but at significantly higher average matter values. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true),
  ('marketing_engine', 'legal', 'get_started', 10, 'Close and CTA', 'Your firm''s growth depends on a consistent pipeline of the right clients for the right practice areas at the right time. Our marketing engine is purpose-built for professional services firms that must balance aggressive growth goals with bar association advertising compliance requirements. Let''s build your firm''s custom growth plan — connect with our legal marketing specialists today. This is a fictional example for demonstration purposes only and does not constitute legal advice.', true)
ON CONFLICT (demo_type, vertical, trigger_key) DO UPDATE SET
  sequence_order = EXCLUDED.sequence_order,
  prompt_text = EXCLUDED.prompt_text,
  response_text = EXCLUDED.response_text,
  active = EXCLUDED.active;

