DELETE FROM vertical_content WHERE vertical_id = 'construction';
INSERT INTO vertical_content (vertical_id, content_type, content_key, content_data) VALUES
  -- Sample Documents (5)
  ('construction', 'sample_doc', 'subcontract_agreement', '{"title": "Concrete Subcontract — Parkview Medical Office", "sections": ["Scope: All formwork, rebar placement, ready-mix supply/placement, flatwork finishing, curing, form removal", "Exclusions: Site utilities, underslab MEP sleeves, elevator pit waterproofing", "Contract Value: $892,000 (schedule of values attached)", "Retainage: 10% until 50% complete, then 5%", "Insurance: GL $2M, Auto $1M, Workers Comp statutory, Umbrella $5M", "Prevailing Wage: Davis-Bacon rates apply; certified payroll required weekly", "Safety: OSHA 10 required for all workers; OSHA 30 required for foremen"]}'),
  ('construction', 'sample_doc', 'change_order_proposal', '{"title": "PCO #019 — Undisclosed Subsurface Obstructions", "project": "Riverside Office Complex", "description": "Encountered abandoned concrete foundation at Grid Lines D-F during excavation for new footings. Obstruction not shown on geotechnical report or as-built drawings provided at bid.", "labor": [{"trade": "Ironworker", "hours": 12, "rate": 94.50}, {"trade": "Operating Engineer", "hours": 8, "rate": 112.00}], "equipment": [{"item": "Excavator standby", "hours": 6, "rate": 185.00}], "materials": [{"item": "Disposal fees", "cost": 1840.00}], "subtotal": 4766.00, "overhead_profit_pct": 15, "total": 5481.00, "time_impact_days": 3, "contract_reference": "Section 7.4 — Concealed Conditions"}'),
  ('construction', 'sample_doc', 'safety_plan', '{"title": "Fall Protection Plan — Westfield Tower Project", "osha_reference": "29 CFR 1926.502", "scope": "All work at elevations above 6 feet", "systems": ["Personal Fall Arrest: Class II full-body harness, 6-ft shock-absorbing lanyard, anchorage rated 5,000 lbs per worker", "Guardrail: 42-inch top rail, 21-inch mid rail, 4-inch toe board", "Hole Covers: Secured, marked HOLE, capable of supporting 2x the anticipated load", "Safety Net: When PFAS and guardrails are infeasible per Section 1926.502(c)"], "competent_person": "Site Safety Officer — daily harness and lanyard inspection required", "training": "All workers must complete 4-hour fall protection training before accessing elevated work areas"}'),
  ('construction', 'sample_doc', 'aia_pay_application', '{"title": "AIA G702/G703 — Application #8", "contractor": "Summit Builders LLC", "project": "Highland Hospital Expansion", "period_ending": "2026-02-28", "schedule_of_values": [{"item": "Structural Concrete", "scheduled": 2400000, "previous": 1680000, "this_period": 240000, "stored": 0, "total_complete": 1920000, "pct": 80, "retainage": 192000}, {"item": "Structural Steel", "scheduled": 1800000, "previous": 1440000, "this_period": 180000, "stored": 45000, "total_complete": 1665000, "pct": 93, "retainage": 166500}, {"item": "MEP Rough-In", "scheduled": 3200000, "previous": 960000, "this_period": 480000, "stored": 120000, "total_complete": 1560000, "pct": 49, "retainage": 156000}], "total_this_period": 900000, "total_retainage": 514500}'),
  ('construction', 'sample_doc', 'rfi_response', '{"title": "RFI #042 Response — CMU Wall Detail at Grid B3", "from": "Architect of Record", "to": "Summit Builders LLC", "response": "The CMU wall at Grid B3 shall be constructed per revised Detail 5/S-204. Reinforcing: #5 at 24 inches on center each way, grouted solid. Contractor shall verify coordination with electrical conduit per drawing E-301 prior to grout placement. No cost or schedule impact anticipated from this clarification.", "cost_impact": "None", "schedule_impact": "None", "attachments": ["Revised Detail 5/S-204"]}'),

  -- Datasets (2)
  ('construction', 'dataset', 'project_cost_performance', '{"title": "Monthly Cost & Schedule Performance — Highland Hospital", "x_axis": "Month", "series": [{"name": "CPI (Cost Performance Index)", "data": [1.02, 1.01, 0.98, 0.97, 0.95, 0.94, 0.93, 0.94, 0.95, 0.96, 0.97, 0.98]}, {"name": "SPI (Schedule Performance Index)", "data": [1.00, 0.99, 0.97, 0.95, 0.93, 0.91, 0.89, 0.90, 0.92, 0.94, 0.96, 0.98]}, {"name": "Budget ($M)", "data": [1.2, 2.5, 3.8, 5.2, 6.8, 8.4, 10.1, 11.8, 13.6, 15.4, 17.2, 19.0]}, {"name": "Actual ($M)", "data": [1.18, 2.48, 3.88, 5.36, 7.16, 8.94, 10.86, 12.55, 14.32, 16.04, 17.73, 19.39]}], "labels": ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]}'),
  ('construction', 'dataset', 'safety_incident_trends', '{"title": "Safety Metrics — Portfolio (8 Quarters)", "x_axis": "Quarter", "series": [{"name": "TRIR", "data": [2.4, 2.1, 1.9, 1.8, 1.6, 1.5, 1.8, 1.4]}, {"name": "Near Misses Reported", "data": [18, 22, 25, 28, 31, 34, 24, 38]}, {"name": "OSHA Recordables", "data": [3, 2, 2, 1, 1, 1, 2, 0]}], "labels": ["Q1-24", "Q2-24", "Q3-24", "Q4-24", "Q1-25", "Q2-25", "Q3-25", "Q4-25"]}'),

  -- Company Profile (1)
  ('construction', 'company_profile', 'demo_company', '{"name": "Summit Builders LLC", "type": "General Contractor", "annual_revenue": "$52M", "employees": 120, "founded": 2008, "headquarters": "Denver, CO", "specialties": ["Commercial Office", "Healthcare", "K-12 Education", "Municipal/Civic"], "bonding_capacity": "$30M single / $75M aggregate", "safety_record": "EMR 0.82 — TRIR 1.4 (3-year average)", "certifications": ["OSHA VPP Star Site", "LEED AP on staff", "DBE-certified partner network"], "notable_projects": ["Highland Hospital Expansion — $67M GMP", "Riverside Unified School District — 3 campuses, $48M", "Northgate Distribution Center — 340,000 SF tilt-up"]}'),

  -- Workflow Templates (3)
  ('construction', 'workflow_template', 'rfi_management', '{"title": "RFI Management Workflow", "steps": [{"step": 1, "name": "RFI Drafted", "description": "Sub or PM drafts RFI with photos, spec references, and drawing markups", "responsible": "Project Manager"}, {"step": 2, "name": "GC Review & Submit", "description": "GC reviews for completeness, logs in RFI register, forwards to architect", "responsible": "Project Manager"}, {"step": 3, "name": "Architect Response", "description": "Architect responds within 14-day contractual window; PM tracks aging", "responsible": "Architect"}, {"step": 4, "name": "Distribution", "description": "Response distributed to affected subs; cost/schedule impact evaluated", "responsible": "Project Manager"}, {"step": 5, "name": "Close & Archive", "description": "RFI closed in log; PCO created if cost/schedule impact identified", "responsible": "Project Manager"}]}'),
  ('construction', 'workflow_template', 'pay_application_processing', '{"title": "AIA Pay Application Workflow", "steps": [{"step": 1, "name": "Sub Pay Apps Received", "description": "Subcontractors submit G702/G703 with updated SOV by the 20th"}, {"step": 2, "name": "Lien Waiver Collection", "description": "Conditional waivers collected from all subs for current billing period"}, {"step": 3, "name": "PM Review & Verification", "description": "PM verifies percent complete against field observations and schedule"}, {"step": 4, "name": "GC Pay App Compiled", "description": "GC assembles master pay app with all sub billing and GC general conditions"}, {"step": 5, "name": "Owner/Architect Review", "description": "Pay app submitted to owner; architect certifies work in place"}, {"step": 6, "name": "Payment & Distribution", "description": "Owner payment received; sub payments issued within contractual timeframe"}]}'),
  ('construction', 'workflow_template', 'closeout_process', '{"title": "Project Closeout Workflow", "steps": [{"step": 1, "name": "Punchlist Generation", "description": "Architect and owner walk site; generate comprehensive punchlist"}, {"step": 2, "name": "Punchlist Completion", "description": "Subs complete punchlist items; GC verifies each item"}, {"step": 3, "name": "O&M Manuals", "description": "Collect operation and maintenance manuals for all building systems"}, {"step": 4, "name": "Warranty Documents", "description": "Compile warranties from all subs and manufacturers"}, {"step": 5, "name": "As-Built Drawings", "description": "Final as-builts reconciled with RFI responses and field changes"}, {"step": 6, "name": "Final Lien Waivers", "description": "Unconditional final lien waivers collected from all subs and suppliers"}, {"step": 7, "name": "Certificate of Occupancy", "description": "Building department issues CO after final inspections pass"}, {"step": 8, "name": "Final Retainage Release", "description": "Final pay app with retainage release submitted after all closeout items accepted"}]}'),

  -- Marketing Copy (3)
  ('construction', 'marketing_copy', 'case_study_elevator', '{"title": "Highland Hospital Expansion — Case Study", "content": "When unforeseen site conditions threatened the schedule and budget of a $67M occupied hospital addition, Summit Builders'' proactive RFI resolution and change order management delivered the project on time and within 1.2% of the original GMP. Zero patient care disruptions, 100% ICRA compliance throughout construction, and a TRIR of 0.6 set a new standard for healthcare construction in the region."}'),
  ('construction', 'marketing_copy', 'capabilities_statement', '{"title": "Summit Builders — Capabilities Overview", "content": "Summit Builders LLC is a Denver-based general contractor delivering commercial, healthcare, and institutional projects from $5M to $75M. With 120 professionals, an EMR of 0.82, and $75M aggregate bonding capacity, we bring the resources of a large firm with the responsiveness of a local builder. Our self-perform concrete and structural steel capabilities eliminate risk on your most critical scopes. From preconstruction through warranty, Summit Builders is your partner for projects that demand precision, safety, and schedule certainty."}'),
  ('construction', 'marketing_copy', 'project_pursuit_letter', '{"title": "SOQ Cover Letter Template", "content": "Dear Selection Committee, Summit Builders LLC is pleased to submit our Statement of Qualifications for the [Project Name]. With [X] comparable projects completed in the past five years totaling over $[Y]M in contract value, our team brings directly relevant experience to your project. Our proposed Project Manager, [Name], has successfully delivered [Z] projects of similar scope, complexity, and delivery method. We are committed to local workforce participation, safety excellence, and transparent communication throughout the project lifecycle. We welcome the opportunity to discuss how Summit Builders can deliver exceptional results for [Owner Name]."}');

