DELETE FROM vertical_content WHERE vertical_id = 'property_mgmt';
INSERT INTO vertical_content (vertical_id, content_type, content_key, content_data) VALUES
  -- Sample Documents (5)
  ('property_mgmt', 'sample_doc', 'residential_lease', '{"title": "Residential Lease Agreement — Unit 4B, Maple Creek Apartments", "sections": ["Term: 12 months commencing April 1, 2026", "Rent: $1,425/month due on the 1st; late fee of $75 after 5-day grace period", "Security Deposit: $1,425 held in escrow per state law", "Occupants: Maximum 2 adults, 1 child", "Utilities: Tenant responsible for electric and gas; water/sewer/trash included", "Pet Policy: One pet under 35 lbs with $300 non-refundable fee and $50/month pet rent", "Maintenance: Tenant to submit requests via online portal; emergency line for after-hours", "Termination: 30-day written notice required; early termination fee equals 2 months rent"]}'),
  ('property_mgmt', 'sample_doc', 'security_deposit_disposition', '{"title": "Security Deposit Disposition — Unit 7A", "tenant": "Sample Tenant", "move_out_date": "2026-02-28", "deposit_held": 1425.00, "deductions": [{"item": "Carpet cleaning — pet stains beyond normal wear", "amount": 275.00}, {"item": "Patching and paint — 3 large holes in bedroom wall", "amount": 180.00}, {"item": "Broken blinds — living room and kitchen", "amount": 120.00}, {"item": "Unpaid rent — prorated final 3 days", "amount": 142.50}], "total_deductions": 717.50, "refund_amount": 707.50, "statutory_deadline": "21 days from vacancy", "mailing_method": "Certified mail to forwarding address on file"}'),
  ('property_mgmt', 'sample_doc', 'hap_contract_summary', '{"title": "Housing Assistance Payment Contract Summary", "housing_authority": "Metro Housing Authority", "unit": "Unit 12C, Oakwood Terrace", "contract_rent": 1280.00, "hap_payment": 940.00, "tenant_portion": 340.00, "utility_allowance": 125.00, "effective_date": "2026-01-01", "annual_anniversary": "2027-01-01", "hqs_inspection": "Passed — January 15, 2026", "special_conditions": "Unit must maintain HQS compliance; 30-day cure period for any deficiency"}'),
  ('property_mgmt', 'sample_doc', 'eviction_notice', '{"title": "3-Day Notice to Pay Rent or Quit", "tenant": "[Tenant Name]", "address": "[Unit Address]", "amount_due": "[Amount]", "period": "March 1-31, 2026", "content": "You are hereby notified that the rent for the above premises totaling $[Amount] is now due and payable. You are required to pay said rent in full within THREE (3) days after service of this notice or quit and deliver possession of the premises. Failure to comply may result in unlawful detainer proceedings. Payment must be made by certified funds at the management office during business hours.", "service_method": "Personal service / posting and mailing"}'),
  ('property_mgmt', 'sample_doc', 'property_inspection_report', '{"title": "Move-Out Inspection Report — Unit 7A", "inspection_date": "2026-03-01", "items": [{"area": "Kitchen", "condition": "Good — appliances clean, countertops intact, minor cabinet wear (normal)", "charge": 0}, {"area": "Bathroom", "condition": "Good — tile and grout clean, fixtures functional, caulking needs refresh (normal)", "charge": 0}, {"area": "Living Room", "condition": "Fair — carpet pet stains, broken blinds", "charge": 395.00}, {"area": "Bedroom", "condition": "Fair — 3 large holes in drywall requiring patch and paint", "charge": 180.00}, {"area": "General", "condition": "Smoke detectors functional, all keys returned, no trash left behind", "charge": 0}], "total_charges": 575.00, "notes": "Broken blind replacement: $120 (2 units). Carpet cleaning for pet damage: $275. Wall repair: $180."}'),

