  ('property_mgmt', 'dataset', 'occupancy_trends', '{"title": "Monthly Occupancy Rate by Property Type", "x_axis": "Month", "series": [{"name": "Market Rate", "data": [94.2, 93.8, 94.5, 95.1, 95.8, 96.2, 96.5, 96.1, 95.4, 94.8, 94.2, 93.6]}, {"name": "Section 8", "data": [98.1, 97.8, 98.2, 98.5, 98.7, 98.9, 99.0, 98.8, 98.6, 98.4, 98.1, 97.9]}, {"name": "Mixed Portfolio", "data": [95.4, 95.0, 95.6, 96.2, 96.8, 97.1, 97.3, 97.0, 96.5, 96.0, 95.5, 95.0]}], "labels": ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]}'),
  ('property_mgmt', 'dataset', 'maintenance_costs', '{"title": "Quarterly Maintenance Spend by Category", "x_axis": "Quarter", "series": [{"name": "HVAC", "data": [18200, 12400, 24600, 19800, 17500, 11800, 23400, 18900]}, {"name": "Plumbing", "data": [8400, 9200, 7800, 10600, 8100, 8800, 7200, 9400]}, {"name": "Electrical", "data": [4200, 3800, 5100, 4600, 3900, 4100, 4800, 4200]}, {"name": "General/Turnover", "data": [15600, 18400, 12200, 14800, 16200, 19100, 13400, 15200]}], "labels": ["Q1-24", "Q2-24", "Q3-24", "Q4-24", "Q1-25", "Q2-25", "Q3-25", "Q4-25"]}'),

  -- Company Profile (1)
  ('property_mgmt', 'company_profile', 'demo_company', '{"name": "Cornerstone Property Group", "type": "Property Management Company", "units_managed": 850, "properties": 12, "annual_revenue": "$14.2M", "employees": 34, "founded": 2012, "headquarters": "Austin, TX", "portfolio_mix": {"market_rate": "62%", "section_8": "28%", "affordable_tax_credit": "10%"}, "key_metrics": {"occupancy": "95.4%", "avg_rent": "$1,380", "collection_rate": "97.1%", "avg_turnover_days": 18}, "services": ["Leasing & Marketing", "Rent Collection & Accounting", "Maintenance & Vendor Management", "Section 8/HCV Administration", "Tenant Screening & Placement", "Financial Reporting & NOI Optimization"]}'),

  -- Workflow Templates (3)
  ('property_mgmt', 'workflow_template', 'tenant_screening', '{"title": "Tenant Screening Workflow", "steps": [{"step": 1, "name": "Application Received", "description": "Applicant completes rental application with consent for background check"}, {"step": 2, "name": "Income Verification", "description": "Verify gross income is at least 3x monthly rent via pay stubs, tax returns, or employer letter"}, {"step": 3, "name": "Credit & Background Check", "description": "Run credit report, criminal background, and eviction history per fair housing guidelines"}, {"step": 4, "name": "Rental History Check", "description": "Contact previous landlords for payment history and lease compliance"}, {"step": 5, "name": "Approval Decision", "description": "Apply consistent criteria per fair housing law; document denial reasons if applicable"}]}'),
  ('property_mgmt', 'workflow_template', 'lease_renewal', '{"title": "Lease Renewal Workflow", "steps": [{"step": 1, "name": "90-Day Review", "description": "Identify leases expiring in 90 days; pull payment history and violation records"}, {"step": 2, "name": "Market Comp Analysis", "description": "Compare current rent to market comps; calculate proposed renewal rate"}, {"step": 3, "name": "Renewal Offer Sent", "description": "Send renewal letter with proposed rate, term options, and response deadline"}, {"step": 4, "name": "Tenant Response", "description": "Track acceptance, counter, or intent to vacate within 30-day response window"}, {"step": 5, "name": "Lease Execution", "description": "Generate renewal addendum for e-signature; update rent roll and accounting"}, {"step": 6, "name": "HAP Adjustment (if applicable)", "description": "Submit rent increase request to housing authority 60 days before anniversary"}]}'),
  ('property_mgmt', 'workflow_template', 'maintenance_request', '{"title": "Maintenance Work Order Lifecycle", "steps": [{"step": 1, "name": "Request Submitted", "description": "Tenant submits request via online portal with description and photos"}, {"step": 2, "name": "Triage & Priority", "description": "Maintenance coordinator assigns priority: emergency (4hr), urgent (24hr), routine (72hr)"}, {"step": 3, "name": "Vendor Dispatch", "description": "Assign to in-house tech or dispatch preferred vendor based on trade type"}, {"step": 4, "name": "Access Coordination", "description": "Notify tenant of scheduled visit; obtain access confirmation"}, {"step": 5, "name": "Work Completed", "description": "Technician completes repair, documents work with photos, updates work order"}, {"step": 6, "name": "Tenant Confirmation", "description": "Automated follow-up to tenant to confirm issue resolved satisfactorily"}, {"step": 7, "name": "Invoice & Close", "description": "Vendor invoice processed, matched to work order, allocated to property GL code"}]}'),

  -- Marketing Copy (3)
  ('property_mgmt', 'marketing_copy', 'owner_pitch', '{"title": "Property Management Services — Owner Pitch", "content": "Cornerstone Property Group maximizes your property''s NOI through proactive leasing, disciplined rent collection, and preventive maintenance programs that reduce emergency costs by 23%. We manage 850 units across Austin with a 95.4% occupancy rate and 97.1% collection rate. Our technology platform gives you real-time visibility into rent rolls, maintenance costs, and financial performance — so you always know exactly how your investment is performing. Whether you own 10 units or 200, we deliver institutional-quality management with hands-on local service."}'),
  ('property_mgmt', 'marketing_copy', 'tenant_welcome', '{"title": "Welcome to Your New Home", "content": "Welcome to Maple Creek Apartments! We''re thrilled you''ve chosen to make this your home. Your online tenant portal is your one-stop resource for rent payments, maintenance requests, and community updates. Rent is due on the 1st of each month — set up autopay for hassle-free payments. For maintenance needs, submit a request through the portal and our team will respond within 24 hours for non-emergency issues. For after-hours emergencies (water leaks, no heat, lockouts), call our 24/7 emergency line. We''re here to make your experience exceptional."}'),
  ('property_mgmt', 'marketing_copy', 'section8_marketing', '{"title": "Housing Choice Vouchers Welcome", "content": "Cornerstone Property Group proudly participates in the Housing Choice Voucher (Section 8) program. We offer quality apartments in well-maintained communities with online rent payment, responsive maintenance, and professional on-site management. Our team handles all HAP contract administration and housing authority coordination, making the process seamless for voucher holders. We comply fully with all fair housing laws and evaluate every application using consistent, non-discriminatory criteria. Contact our leasing office today to schedule a tour and learn about available units."}');

