  -- Sample Documents (5)
  ('legal', 'sample_doc', 'engagement_letter', '{"title": "Client Engagement Letter — Estate Planning", "sections": ["Scope: Preparation of revocable living trust, pour-over will, durable power of attorney, and healthcare directive", "Fees: Flat fee of $3,500 for the estate planning package; hourly rate of $425 for additional work", "Retainer: $2,000 initial retainer deposited to firm IOLTA account", "Billing: Monthly invoices with detailed time entries; payment due within 30 days", "Termination: Either party may terminate upon 30 days written notice; earned fees non-refundable", "File Retention: Client file retained for 7 years per firm policy"], "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),
  ('legal', 'sample_doc', 'revocable_trust', '{"title": "Revocable Living Trust — Sample Excerpt", "content": "ARTICLE I: CREATION OF TRUST. The Grantor hereby creates this Revocable Living Trust and transfers the property described in Schedule A to the Trustee, to be held, administered, and distributed according to the terms of this agreement. ARTICLE II: AMENDMENT AND REVOCATION. The Grantor reserves the right to amend, modify, or revoke this Trust at any time during the Grantor''s lifetime. ARTICLE III: DISTRIBUTIONS DURING LIFETIME. The Trustee shall distribute to or for the benefit of the Grantor such amounts of income and principal as the Grantor may request. ARTICLE IV: SUCCESSOR TRUSTEE. Upon the Grantor''s incapacity or death, [Successor Name] shall serve as Successor Trustee with full authority to manage, invest, and distribute trust assets.", "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),
  ('legal', 'sample_doc', 'demand_letter', '{"title": "Pre-Litigation Demand Letter — Breach of Contract", "content": "Dear [Opposing Party]: This firm represents [Client Name] regarding your breach of the Services Agreement dated [Date]. Specifically, you have failed to deliver the contracted services by the agreed deadline and have not cured the breach despite written notice provided on [Date]. Our client has suffered direct damages of $[Amount] in lost revenue and $[Amount] in costs to engage replacement services. We demand payment of $[Total] within thirty (30) days of this letter. Failure to resolve this matter will result in the commencement of formal legal proceedings without further notice.", "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),
  ('legal', 'sample_doc', 'nda_agreement', '{"title": "Mutual Non-Disclosure Agreement", "sections": ["Parties: [Company A] and [Company B]", "Purpose: Evaluation of potential business transaction", "Confidential Information: All non-public business, financial, technical, and legal information", "Term: 2 years from effective date", "Exclusions: Publicly available information, independently developed information, compelled disclosures", "Return/Destroy: All materials returned or certified destroyed within 30 days of termination", "Governing Law: [State] law; disputes resolved by binding arbitration"], "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),
  ('legal', 'sample_doc', 'discovery_request', '{"title": "First Set of Interrogatories — Sample", "interrogatories": ["State the full legal name, address, and position of each person who participated in negotiating the Agreement at issue.", "Identify all documents relating to the performance or non-performance of obligations under the Agreement.", "State with specificity each act or omission you contend constitutes a breach of the Agreement.", "For each item of damages claimed, state the amount, method of calculation, and supporting documentation.", "Identify each expert witness you intend to call at trial, including qualifications and subject matter of testimony."], "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),

  -- Datasets (2)
  ('legal', 'dataset', 'firm_financials', '{"title": "Monthly Firm Performance Metrics", "x_axis": "Month", "series": [{"name": "Realization Rate (%)", "data": [88, 86, 89, 87, 85, 90, 91, 88, 87, 89, 86, 92]}, {"name": "Collection Rate (%)", "data": [82, 84, 81, 85, 83, 86, 88, 85, 84, 87, 83, 90]}, {"name": "Billable Hours", "data": [1420, 1380, 1450, 1410, 1350, 1480, 1520, 1460, 1400, 1490, 1380, 1550]}], "labels": ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"], "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),
  ('legal', 'dataset', 'matter_profitability', '{"title": "Practice Area Profitability Analysis", "categories": [{"name": "Estate Planning", "revenue": 1260000, "cost": 453600, "margin_pct": 64, "avg_matter_value": 4200, "matters_closed": 300}, {"name": "Commercial Litigation", "revenue": 1680000, "cost": 991200, "margin_pct": 41, "avg_matter_value": 28000, "matters_closed": 60}, {"name": "Transactional/Corporate", "revenue": 840000, "cost": 352800, "margin_pct": 58, "avg_matter_value": 7000, "matters_closed": 120}, {"name": "Regulatory Compliance", "revenue": 420000, "cost": 193200, "margin_pct": 54, "avg_matter_value": 5250, "matters_closed": 80}], "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),

  -- Company Profile (1)
  ('legal', 'company_profile', 'demo_company', '{"name": "Whitfield & Associates", "type": "Law Firm", "attorneys": 8, "staff": 12, "annual_revenue": "$4.2M", "founded": 2005, "headquarters": "Charlotte, NC", "practice_areas": ["Estate Planning & Trust Administration", "Commercial Litigation", "Business Formation & Transactions", "Regulatory Compliance"], "key_metrics": {"realization_rate": "87.3%", "collection_rate": "91.2%", "avg_days_to_payment": 44, "billable_target": 1800}, "technology": ["Cloud-based case management", "IOLTA trust accounting software", "AI-assisted document review", "E-filing integrated with state courts"], "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),

  -- Workflow Templates (3)
  ('legal', 'workflow_template', 'client_intake', '{"title": "New Matter Intake Workflow", "steps": [{"step": 1, "name": "Initial Contact", "description": "Prospective client contacts firm; intake paralegal collects matter type, parties, and key dates"}, {"step": 2, "name": "Conflicts Check", "description": "Run all named parties and affiliates against firm database; document results"}, {"step": 3, "name": "Attorney Consultation", "description": "Schedule consultation with practice area attorney; collect relevant documents"}, {"step": 4, "name": "Engagement Decision", "description": "Attorney evaluates merit, capacity, and conflicts; approve or decline representation"}, {"step": 5, "name": "Engagement Letter & Retainer", "description": "Generate engagement letter; collect signed agreement and IOLTA retainer deposit"}, {"step": 6, "name": "Matter Opened", "description": "Create matter in case management system; assign billing codes, responsible attorney, and docketing"}], "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),
  ('legal', 'workflow_template', 'discovery_management', '{"title": "Discovery Lifecycle Workflow", "steps": [{"step": 1, "name": "Litigation Hold", "description": "Issue preservation notice to client; identify custodians and data sources"}, {"step": 2, "name": "Discovery Plan", "description": "Develop discovery strategy; draft propounding and responding timelines"}, {"step": 3, "name": "Document Collection", "description": "Collect responsive documents from client; process through review platform"}, {"step": 4, "name": "Document Review", "description": "Attorney review for responsiveness and privilege; code documents systematically"}, {"step": 5, "name": "Privilege Log", "description": "Generate privilege log for withheld documents per court standing order"}, {"step": 6, "name": "Production", "description": "Produce responsive, non-privileged documents in agreed format with Bates numbering"}, {"step": 7, "name": "Deposition Preparation", "description": "Prepare witnesses using produced documents; schedule depositions within discovery period"}], "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),
  ('legal', 'workflow_template', 'billing_cycle', '{"title": "Monthly Billing Process", "steps": [{"step": 1, "name": "Timekeeper Entry Deadline", "description": "All attorneys and paralegals must enter time by the 3rd business day of the following month"}, {"step": 2, "name": "Pre-Bill Review", "description": "Billing partner reviews pre-bills for accuracy, write-downs, and client billing guidelines"}, {"step": 3, "name": "Invoice Generation", "description": "Final invoices generated with detailed time entries, expense reimbursements, and trust account activity"}, {"step": 4, "name": "Client Distribution", "description": "Invoices distributed via client portal or email with secure payment link"}, {"step": 5, "name": "Collections Follow-Up", "description": "Automated reminders at 30, 60, and 90 days; escalate to billing partner for accounts over 90 days"}], "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),

  -- Marketing Copy (3)
  ('legal', 'marketing_copy', 'estate_planning_guide', '{"title": "Estate Planning Checklist — Free Download", "content": "Is your estate plan complete? Most families overlook critical elements that can lead to costly probate, family disputes, and unintended tax consequences. Our comprehensive Estate Planning Checklist covers the 12 essential documents and decisions every family should address — from revocable trusts and powers of attorney to beneficiary designations and digital asset planning. Download your free copy and schedule a complimentary 30-minute review with one of our estate planning attorneys.", "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),
  ('legal', 'marketing_copy', 'firm_overview', '{"title": "Whitfield & Associates — Firm Overview", "content": "Whitfield & Associates has served individuals, families, and businesses in the Charlotte metropolitan area since 2005. Our eight attorneys bring focused expertise in estate planning, commercial litigation, business transactions, and regulatory compliance. We combine the attentiveness of a boutique firm with the capability to handle complex, high-stakes matters. Our commitment to client communication, transparent billing, and practical solutions has earned us a reputation as trusted advisors across the Carolinas.", "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}'),
  ('legal', 'marketing_copy', 'seminar_invitation', '{"title": "Client Education Seminar — Estate Planning Essentials", "content": "Join Whitfield & Associates for a complimentary estate planning seminar on [Date] at [Location]. Our attorneys will cover: Why every adult needs a will and trust, How to protect assets from probate and estate taxes, Powers of attorney and healthcare directives explained, and Common mistakes that can cost your family thousands. Light refreshments provided. Space is limited — RSVP by [Date] to reserve your seat. Attendees receive a complimentary 30-minute consultation.", "disclaimer": "This is a fictional example for demonstration purposes only and does not constitute legal advice."}')
